        [elements.authSignInBtn, elements.authSignUpBtn].forEach(el => {
            if (!el) return;
            el.disabled = !configured || signedIn;
        });

        if (elements.authSignOutBtn) {
            elements.authSignOutBtn.disabled = !configured || !signedIn;
        }

        renderStudioHomeDashboard();
