function getMasteryCheckRemainingCount() {
    if (!isMasteryCheckMode()) return 0;
    if (state.masteryCheckFinished) return 0;

    if (state.masteryCheckInCheckpoint) {
        return Math.max(0, state.questionQueue.length - state.currentIndex);
    }

    return Math.max(0, state.questionQueue.length - state.currentIndex);
}

function resetMasteryCheckState() {
    state.masteryCheckPendingJump = false;
    state.masteryCheckPendingAdvance = false;
    state.masteryCheckPendingCheckpointStart = false;
    state.masteryCheckPendingCheckpointComplete = false;
    state.masteryCheckInCheckpoint = false;
    state.masteryCheckFinished = false;
    state.masteryCheckSegmentQuestions = [];
    state.masteryCheckSegmentIds = new Set();
    state.masteryCheckCheckpointSolvedIds = new Set();
    state.masteryCheckResumeQueue = [];
    state.masteryCheckResumeIndex = 0;
    state.masteryCheckMasteredIds = new Set();
}

function startMasteryCheckCheckpoint() {
    const checkpointQuestions = [...state.masteryCheckSegmentQuestions];
    const checkpointIds = new Set(checkpointQuestions.map(question => question.id));

    state.masteryCheckResumeQueue = [...state.questionQueue];
    state.masteryCheckResumeIndex = state.questionQueue
        .slice(0, state.currentIndex + 1)
        .filter(question => !checkpointIds.has(question.id)).length;

    state.questionQueue = checkpointQuestions;
    state.currentIndex = 0;
    state.masteryCheckInCheckpoint = true;
    state.masteryCheckCheckpointSolvedIds = new Set();
    state.masteryCheckPendingCheckpointStart = false;
    state.masteryCheckPendingCheckpointComplete = false;
    state.masteryCheckPendingAdvance = false;
    state.masteryCheckPendingJump = false;
    state.masteryCheckSegmentQuestions = [];
    state.masteryCheckSegmentIds = new Set();
}

function finishMasteryCheckCheckpoint() {
    const masteredIds = new Set(state.questionQueue.map(question => question.id));

    masteredIds.forEach(id => state.masteryCheckMasteredIds.add(id));

    const filteredQueue = state.masteryCheckResumeQueue.filter(question => !masteredIds.has(question.id));

    state.questionQueue = filteredQueue;
    state.currentIndex = filteredQueue.length ? Math.min(state.masteryCheckResumeIndex, filteredQueue.length - 1) : 0;
    state.masteryCheckInCheckpoint = false;
    state.masteryCheckCheckpointSolvedIds = new Set();
    state.masteryCheckResumeQueue = [];
    state.masteryCheckResumeIndex = 0;
    state.masteryCheckPendingCheckpointComplete = false;
    state.masteryCheckPendingAdvance = false;
    state.masteryCheckPendingJump = false;

    if (filteredQueue.length === 0) {
        state.masteryCheckFinished = true;
    }
}

// ================= FEEDBACK HELPER =================
function setFeedback(text, isCorrect) {
    const fb = elements.progressSideFeedbackEl;
    if (!fb) return;

    if (isAnswerFeedbackHidden()) {
        clearFeedback();
        return;
    }

    fb.innerText = text;
    fb.classList.remove('correct', 'incorrect');
    fb.classList.add(isCorrect ? 'correct' : 'incorrect');
}

async function persistQuestionStarState(question, isStarred) {
    if (!canPersistQuestionStarState(question)) {
        return false;
    }

    const payload = {
        user_id: state.auth.user.id,
        question_id: question.sourceQuestionId,
        is_starred: !!isStarred
    };

    const { error } = await state.auth.client
        .from('user_question_state')
        .upsert(payload, { onConflict: 'user_id,question_id' });

    if (error) throw error;
    return true;
}

function applyQuestionStarStateAcrossDeck(sourceQuestionId, isStarred) {
    const targetId = normalizeSheetText(sourceQuestionId);
    if (!targetId) return;

    const applyState = question => {
        if (normalizeSheetText(question?.sourceQuestionId) === targetId) {
            question.isStarred = !!isStarred;
        }
    };

    state.sourceQuestions.forEach(applyState);
    state.questions.forEach(applyState);
    state.questionQueue.forEach(applyState);
    if (Array.isArray(state.auth.studioQuizQuestions)) {
        let changedStudioRow = false;
        state.auth.studioQuizQuestions.forEach(question => {
            if (normalizeSheetText(question?.id) === targetId) {
                question.isStarred = !!isStarred;
                changedStudioRow = true;
            }
        });
        if (changedStudioRow && state.auth.quizStudioOpen) {
            renderStudioQuestionList();
        }
    }
}

async function toggleCurrentQuestionStarState() {
    const currentQuestion = state.questionQueue[state.currentIndex];
    if (!canPersistQuestionStarState(currentQuestion) || state.auth.starringInFlight) {
        return;
    }

    const nextStarred = !currentQuestion.isStarred;
    state.auth.starringInFlight = true;
    syncQuestionStarButton();

    try {
        await persistQuestionStarState(currentQuestion, nextStarred);
        applyQuestionStarStateAcrossDeck(currentQuestion.sourceQuestionId, nextStarred);

        if (nextStarred && isExcludeStarredEnabled()) {
            applyFilteredQuestionsToSession({ resetSession: false });
        } else {
            syncQuestionStarButton();
            updateProgress();
        }
    } catch (error) {
        console.error('Could not update question star state:', error);
    } finally {
        state.auth.starringInFlight = false;
        syncQuestionStarButton();
    }
}

function applyQuestionOutcome(q, isCorrect, options = {}) {
    const { useSideFeedback = true } = options;
    recordProgressModeOutcome(q, isCorrect);
    maybeAutoStarQuestionFromOutcome(q, isCorrect);
    maybeUnstarQuestionFromOutcome(q, isCorrect);
    if (state.studyTimer.scope === 'question') {
        stopStudyTimer({ clearDisplay: false });
    }

    if (isCorrect) {
        clearPendingLearningResource();
        if (useSideFeedback) {
            setFeedback('Correct!', true);
        } else {
            clearFeedback();
        }
        handleCorrectAnswer();
    } else {
        queueLearningResourceIfEligible(q);
        if (useSideFeedback) {
            setFeedback('Incorrect!', false);
        } else {
            clearFeedback();
        }
        handleWrongAnswer();
    }

    if (maybeAutoFinishActiveQuizChallengeAfterAnswer()) {
        return;
    }

    if (isRetryMode() || isProgressMode()) {
        updateProgress();
    }

    updateNavigationButtons();
}

// ================= PROGRESS =================
function getMasteryCheckCompletedForProgressBar(total) {
    if (!isMasteryCheckMode()) return 0;
    if (state.masteryCheckFinished) return total;

    const activeQuestionIds = new Set((state.questions || []).map(question => question.id));
    const masteredCount = [...state.masteryCheckMasteredIds]
        .filter(questionId => activeQuestionIds.has(questionId))
        .length;

    return masteredCount + state.currentIndex;
}

function updateProgress() {
    const total = state.questions.length;
    const progressFillEl = document.getElementById('progressFill');
    let remaining = 0;
    let completed = 0;
    let percent = 0;
    let useReviewProgressAppearance = false;
    let overrideProgressText = '';

    if (isProgressMode()) {
        if (state.normalFinished) {
            const missedCount = getProgressMissedQuestions().length;
            if (isAnswerFeedbackHidden()) {
                remaining = 0;
                completed = total;
                percent = total > 0 ? 100 : 0;
                overrideProgressText = missedCount > 0 ? 'Review ready' : 'Complete';
            } else {
                remaining = missedCount;
                completed = total - missedCount;
                percent = total > 0 ? (completed / total) * 100 : 0;
            }
        } else {
            remaining = state.questionQueue.length - state.currentIndex;
            completed = total - remaining;
            percent = total > 0 ? (completed / total) * 100 : 0;
        }
    } else if (isRetentionMode()) {
        remaining = state.retentionFinished ? 0 : (state.questionQueue.length - state.currentIndex);
        completed = total - remaining;
        percent = total > 0 ? (completed / total) * 100 : 0;
    } else if (isRetryMode()) {
        remaining = state.questionQueue.length;
        completed = total - remaining;
        percent = total > 0 ? (completed / total) * 100 : 0;
    } else if (isMasteryCheckMode()) {
        remaining = state.masteryCheckFinished ? 0 : getMasteryCheckRemainingCount();

        if (state.masteryCheckInCheckpoint) {
            const checkpointTotal = state.questionQueue.length;
            completed = state.currentIndex;
            percent = checkpointTotal > 0 ? (completed / checkpointTotal) * 100 : 0;
            useReviewProgressAppearance = true;
        } else {
            completed = getMasteryCheckCompletedForProgressBar(total);
            percent = total > 0 ? (completed / total) * 100 : 0;
        }
    } else {
        remaining = state.normalFinished ? 0 : (state.questionQueue.length - state.currentIndex);
        completed = total - remaining;
        percent = total > 0 ? (completed / total) * 100 : 0;
    }

    if (remaining < 0) remaining = 0;
    if (remaining > total) remaining = total;
    if (completed < 0) completed = 0;
    if (completed > total) completed = total;
    if (percent < 0) percent = 0;
    if (percent > 100) percent = 100;

    const timerText = getStudyTimerDisplayText();
    const remainingText = overrideProgressText || (isNarrowIPhoneViewport() ? `${remaining}` : `${remaining} remaining`);
    elements.progressTextEl.innerText = timerText ? `${remainingText}  ${timerText}` : remainingText;
    updateBuildUpProgressIndicator();

    if (progressFillEl) {
        progressFillEl.style.width = `${percent}%`;
        progressFillEl.style.background = useReviewProgressAppearance ? '#f4c542' : '';
    }
}

// ================= FINISH CHECK =================
function isQuizFinished() {
    if (isRetentionMode()) return state.retentionFinished;
    if (isRetryMode()) return state.questionQueue.length === 0;
    if (isMasteryCheckMode()) return state.masteryCheckFinished;
    return state.normalFinished;
}

function renderProgressModeFinishState() {
    const missedQuestions = getProgressMissedQuestions();
    const missedCount = missedQuestions.length;
    const percent = getProgressScorePercent();
    const hideFeedback = isAnswerFeedbackHidden();

    elements.questionTextEl.style.display = 'block';
    elements.questionTextEl.innerText = hideFeedback
        ? 'Progress Round Complete'
        : (percent >= 100 ? 'Progress Complete!' : (percent + '% complete'));
    elements.optionsContainer.style.display = 'flex';
    elements.optionsContainer.innerHTML = '';

    const summary = document.createElement('div');
    summary.className = 'progress-mode-summary';

    const message = document.createElement('div');
    message.className = 'progress-mode-message';
    if (missedCount > 0) {
        if (hideFeedback) {
            message.innerText = state.progressRetryActive
                ? 'Review round complete. Continue with the remaining review set.'
                : 'Round complete. Continue with the review set.';
        } else {
            if (isTetherBuildUpEnabled()) {
                const reviewCount = expandQuestionsWithTetherBuildUp(missedQuestions, state.questions).length;
                const questionLabel = reviewCount === 1 ? 'question' : 'questions';
                message.innerText = 'Review set ready with ' + reviewCount + ' ' + questionLabel + '. Build Up strings stay together.';
            } else {
                const questionLabel = missedCount === 1 ? 'question' : 'questions';
                const retryPrefix = state.progressRetryActive ? 'You still missed ' : 'You missed ';
                message.innerText = retryPrefix + missedCount + ' ' + questionLabel + '. Try again with only the missed questions.';
            }
        }
    } else {
        message.innerText = hideFeedback
            ? 'Progress session complete.'
            : '100% complete. You finished this Progress Mode session.';
    }
    summary.appendChild(message);

    if (missedCount > 0) {
        const retryBtn = document.createElement('button');
        retryBtn.type = 'button';
        retryBtn.className = 'auth-action-btn progress-mode-retry-btn';
        retryBtn.innerText = hideFeedback ? 'Continue Review' : 'Try Again';
        retryBtn.addEventListener('click', startProgressModeRetry);
        summary.appendChild(retryBtn);
    }

    elements.optionsContainer.appendChild(summary);
}

// ================= SHOW QUESTION =================
function showQuestion() {
    if (!state.questions.length) {
        renderSelectionPrompt(state.emptyQuizMessage || 'Choose a folder and a quiz.');
        return;
    }

    clearQuestionUI();
    state.questionAnswered = false;
    state.flashcardFlipped = false;
    state.multipleAnswerSelection = new Set();

    if (isRetentionMode()) {
        state.retentionAnswerLocked = false;
    }

    if (isQuizFinished()) {
        stopStudyTimer({ clearDisplay: false });
        if (isProgressMode()) {
            renderProgressModeFinishState();
        } else {
            elements.questionTextEl.style.display = 'block';
            elements.questionTextEl.innerText = 'Quiz Finished!';
            elements.optionsContainer.style.display = 'none';
        }
        elements.imageContainer.style.display = '';
        elements.questionImage.style.display = 'none';
        elements.questionImage.src = '';
        state.currentQuestionType = '';
        updateViewportClasses();
        updateProgress();
        updateNavigationButtons();
        syncQuestionStarButton();
        maybeCompleteActiveQuizChallenge();
        maybeOpenCompletionChallengePrompt();
        return;
    }

    if (state.currentIndex < 0) state.currentIndex = 0;
    if (state.currentIndex >= state.questionQueue.length) state.currentIndex = state.questionQueue.length - 1;

    const q = state.questionQueue[state.currentIndex];
    state.currentQuestionType = q.type || '';
    state.currentQuestionHasImage = !!q.image;
    const shouldDelayOptions = isOptionDelayEnabledForQuestion(q);
    startAutoStarQuestionWindow(q);
    if (shouldDelayOptions) {
        pauseStudyTimerForOptionDelay();
    } else {
        syncStudyTimerForCurrentQuestion();
    }
    updateViewportClasses();
    if (shouldMountQuestionStarButtonBesideStudyMenu(q)) {
        mountQuestionStarButtonBesideStudyMenu();
    }
    elements.optionsContainer.style.display = 'none';

    if (q.type === 'flashcard') {
        elements.questionTextEl.innerText = '';
        elements.questionTextEl.style.display = 'none';
        elements.imageContainer.style.display = 'none';
        elements.questionImage.style.display = 'none';
        elements.questionImage.src = '';
        showFlashcard(q);
        updateProgress();
        updateNavigationButtons();
        syncQuestionStarButton();
        return;
    }

    elements.questionTextEl.style.display = 'block';
    setMathChemFormattedText(elements.questionTextEl, q.question);
    elements.imageContainer.style.display = '';
    elements.questionImage.style.display = q.image ? 'block' : 'none';
    elements.questionImage.src = q.image || '';
    if ((q.type === 'diagrams' || q.type === 'typed answer' || q.type === 'multiple choice') && q.image) {
        renderDiagramStudyLabels(q.diagramLabels || []);
    } else {
        clearDiagramStudyLabels();
    }

    if (q.type === 'multiple choice' || q.type === 'diagrams') {
        showMC(q);
    } else if (q.type === 'typed answer') {
        showTypedAnswer(q);
    } else if (q.type === 'hierarchy') {
        showHierarchy(q);
    } else if (q.type === 'classify') {
        showClassify(q);
    }

    updateProgress();
    updateNavigationButtons();
    syncQuestionStarButton();
}

// ================= MULTIPLE CHOICE =================
function isGlobalShuffleAnswersSupportedQuestion(question = {}) {
    if (question?.allowMultipleAnswers) return false;
    return question?.type === 'multiple choice' || question?.type === 'diagrams';
}

function isGlobalShuffleAnswersEnabled() {
    return !!state.globalShuffleAnswers.enabled;
}

function getMultipleChoiceOptionEntries(question = {}) {
    return (question.options || []).map((optionText, index) => ({
        text: normalizeSheetText(optionText),
        image: normalizeSheetText((question.optionImages || [])[index]),
        explanation: normalizeSheetText((question.explanations || [])[index])
    })).filter(entry => entry.text || entry.image);
}

function getMultipleChoiceOptionValue(entry = {}) {
    return normalizeSheetText(entry.text) || normalizeSheetText(entry.image);
}

function getMultipleChoiceOptionKey(entry = {}) {
    return getMultipleChoiceOptionValue(entry).toLocaleLowerCase();
}

function getQuestionGlobalShuffleKey(question = {}) {
    return normalizeSheetText(question?.id || question?.sourceQuestionId);
}

function findCorrectMultipleChoiceEntry(question = {}, optionEntries = []) {
    const correctValue = normalizeSheetText(question.correct);
    if (!correctValue) return null;

    const match = optionEntries.find(entry => getMultipleChoiceOptionValue(entry) === correctValue);
    if (match) return { ...match };

    return {
        text: correctValue,
        image: '',
        explanation: ''
    };
}

function buildGlobalShuffleAnswerEntries(question = {}, localOptionEntries = []) {
    if (!isGlobalShuffleAnswersEnabled() || !isGlobalShuffleAnswersSupportedQuestion(question)) {
        return [...localOptionEntries];
    }

    const correctEntry = findCorrectMultipleChoiceEntry(question, localOptionEntries);
    const correctValue = normalizeSheetText(question.correct);
    const targetCount = Math.max(localOptionEntries.length, 1);

    if (!correctEntry || !correctValue || targetCount <= 1) {
        return [...localOptionEntries];
    }

    const currentQuestionKey = getQuestionGlobalShuffleKey(question);
    const selected = [{ ...correctEntry }];
    const usedKeys = new Set([getMultipleChoiceOptionKey(correctEntry)]);

    const sourceQuestions = (state.questions.length ? state.questions : state.questionQueue)
        .filter(candidate => {
            if (!isGlobalShuffleAnswersSupportedQuestion(candidate)) return false;
            if (candidate.type !== question.type) return false;
            const candidateKey = getQuestionGlobalShuffleKey(candidate);
            return !currentQuestionKey || candidateKey !== currentQuestionKey;
        });

    const globalDecoys = [];
    sourceQuestions.forEach(candidate => {
        getMultipleChoiceOptionEntries(candidate).forEach(entry => {
            const value = getMultipleChoiceOptionValue(entry);
            const key = getMultipleChoiceOptionKey(entry);
            if (!value || value === correctValue || usedKeys.has(key)) return;
            usedKeys.add(key);
            globalDecoys.push({ ...entry });
        });
    });

    shuffleArray(globalDecoys);

    while (selected.length < targetCount && globalDecoys.length) {
        selected.push(globalDecoys.shift());
    }

    if (selected.length < targetCount) {
        localOptionEntries.forEach(entry => {
            if (selected.length >= targetCount) return;
            const value = getMultipleChoiceOptionValue(entry);
            const key = getMultipleChoiceOptionKey(entry);
            if (!value || value === correctValue || usedKeys.has(key)) return;
            usedKeys.add(key);
            selected.push({ ...entry });
        });
    }

    shuffleArray(selected);
    return selected;
}

function ensureOptionHideControl(block) {
    if (!block) return null;
    const feedback = block.querySelector('.option-feedback');
    if (!feedback) return null;

    let hideBtn = block.querySelector('.option-hide-btn');
    if (!hideBtn) {
        hideBtn = document.createElement('button');
        hideBtn.type = 'button';
        hideBtn.className = 'option-hide-btn';
        hideBtn.setAttribute('aria-label', 'Hide option');
        hideBtn.title = 'Hide option';
        hideBtn.textContent = '⊘';
    }

    if (hideBtn.parentElement !== feedback) {
        feedback.innerHTML = '';
        feedback.appendChild(hideBtn);
    }

    return hideBtn;
}

function resetOptionFeedbackLane(block) {
    if (!block) return null;
    const feedback = block.querySelector('.option-feedback');
    if (!feedback) return null;
    feedback.innerText = '';
    feedback.classList.remove('correct-mark', 'incorrect-mark');
    return ensureOptionHideControl(block);
}

function ensureMultipleChoiceOptionBlocks(count) {
    const container = elements.optionsContainer;
    let resetBtn = document.getElementById('resetHiddenOptionsBtn');
    if (resetBtn) resetBtn.remove();

    const getBlocks = () => Array.from(container.querySelectorAll('.option-block'));
    let blocks = getBlocks();

    while (blocks.length < count) {
        const block = document.createElement('div');
        block.className = 'option-block';
        block.innerHTML = `
            <div class="option-row">
              <button class="optionBtn" type="button"></button>
              <div class="option-feedback"><button class="option-hide-btn" type="button" aria-label="Hide option" title="Hide option">⊘</button></div>
            </div>
            <div class="explanation"></div>
        `;
        container.appendChild(block);
        blocks = getBlocks();
    }

    blocks.forEach((block, index) => {
        const hideBtn = resetOptionFeedbackLane(block);
        block.classList.remove('option-eliminated');
        block.style.display = index < count ? '' : 'none';
        if (hideBtn) {
            hideBtn.disabled = false;
            hideBtn.classList.remove('hidden');
        }
    });

    resetBtn = document.createElement('button');
    resetBtn.type = 'button';
    resetBtn.id = 'resetHiddenOptionsBtn';
    resetBtn.className = 'reset-hidden-options-btn hidden';
    resetBtn.innerText = 'Reset hidden options';
    resetBtn.addEventListener('click', resetHiddenOptions);
    container.appendChild(resetBtn);

    return getBlocks();
}

function updateResetHiddenOptionsButton() {
    const resetBtn = document.getElementById('resetHiddenOptionsBtn');
    if (!resetBtn) return;
    const hasHiddenOptions = Array.from(elements.optionsContainer.querySelectorAll('.option-block'))
        .some(block => block.classList.contains('option-eliminated'));
    resetBtn.classList.toggle('hidden', !hasHiddenOptions);
}

function clearTypedAnswerUI() {
    if (elements.typedAnswerContainer) {
        elements.typedAnswerContainer.classList.add('hidden');
        elements.typedAnswerContainer.classList.remove('answered-correct', 'answered-incorrect');
    }
    if (elements.typedAnswerInput) {
        elements.typedAnswerInput.value = '';
        elements.typedAnswerInput.disabled = false;
    }
    if (elements.typedAnswerSubmitBtn) {
        elements.typedAnswerSubmitBtn.disabled = false;
    }
    if (elements.typedAnswerResult) elements.typedAnswerResult.textContent = '';
    if (elements.typedAnswerExplanation) elements.typedAnswerExplanation.innerHTML = '';
}

function getTypedAnswerAcceptedValues(question = {}) {
    const variants = normalizeTypedAnswerVariants(question.acceptedAnswers || []);
    return variants.length ? variants : normalizeTypedAnswerVariants([question.correct]);
}

function formatTypedAnswerAcceptedValuesLabel(values = []) {
    const cleanValues = normalizeTypedAnswerVariants(values);
    if (!cleanValues.length) return '';
    if (cleanValues.length === 1) return cleanValues[0];
    if (cleanValues.length === 2) return `${cleanValues[0]} or ${cleanValues[1]}`;
    return `${cleanValues.slice(0, -1).join(', ')}, or ${cleanValues[cleanValues.length - 1]}`;
}

function showTypedAnswer(q) {
    if (!elements.typedAnswerContainer || !elements.typedAnswerInput || !elements.typedAnswerSubmitBtn) return;
    elements.optionsContainer.style.display = 'none';
    clearTypedAnswerUI();
    elements.typedAnswerContainer.classList.remove('hidden');
    elements.typedAnswerSubmitBtn.onclick = () => checkTypedAnswer();
    elements.typedAnswerInput.onkeydown = event => {
        if (event.key === 'Enter') {
            event.preventDefault();
            checkTypedAnswer();
        }
    };
    setTimeout(() => {
        if (!window.matchMedia('(hover: none) and (pointer: coarse)').matches) elements.typedAnswerInput?.focus();
    }, 30);
}

function checkTypedAnswer() {
    if (isQuizFinished()) return;
    if (state.questionAnswered) return;
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
    if (isRetentionMode() && state.retentionAnswerLocked) return;

    const q = state.questionQueue[state.currentIndex];
    if (!q || q.type !== 'typed answer') return;
    const rawAnswer = normalizeSheetText(elements.typedAnswerInput?.value);
    if (!rawAnswer) {
        if (elements.typedAnswerResult) elements.typedAnswerResult.textContent = 'Enter an answer first.';
        elements.typedAnswerInput?.focus();
        return;
    }

    const acceptedValues = getTypedAnswerAcceptedValues(q);
    const normalizedAnswer = normalizeTypedAnswerMatchValue(rawAnswer);
    const isCorrect = acceptedValues.some(value => normalizeTypedAnswerMatchValue(value) === normalizedAnswer);
    const hideFeedback = isAnswerFeedbackHidden();

    state.questionAnswered = true;
    if (elements.typedAnswerInput) elements.typedAnswerInput.disabled = true;
    if (elements.typedAnswerSubmitBtn) elements.typedAnswerSubmitBtn.disabled = true;

    if (elements.typedAnswerContainer) {
        elements.typedAnswerContainer.classList.toggle('answered-correct', isCorrect && !hideFeedback);
        elements.typedAnswerContainer.classList.toggle('answered-incorrect', !isCorrect && !hideFeedback);
    }

    if (!hideFeedback && elements.typedAnswerResult) {
        const correctLabel = formatTypedAnswerAcceptedValuesLabel(acceptedValues) || q.correct || '';
        elements.typedAnswerResult.innerHTML = isCorrect
            ? `<span class="typed-answer-correct-mark">✔ Correct</span>`
            : `<span class="typed-answer-incorrect-mark">✖ Incorrect</span><span class="typed-answer-correct-answer"> Correct answer: ${escapeHtml(correctLabel)}</span>`;
    }

    if (!hideFeedback && elements.typedAnswerExplanation) {
        const explanation = normalizeSheetText(q.correctExplanation || '');
        setMathChemFormattedText(elements.typedAnswerExplanation, explanation);
    }

    applyQuestionOutcome(q, isCorrect);

    if (isSpeedMode()) {
        setTimeout(nextQuestion, CONFIG.speedDelay);
    }
}

function isOptionsScrollQuestionType() {
    return state.currentQuestionType === 'multiple choice' || state.currentQuestionType === 'diagrams' || state.currentQuestionType === 'typed answer';
}

function getElementRenderedScaleY(element) {
    if (!element) return 1;

    const rect = element.getBoundingClientRect();
    const layoutHeight = element.offsetHeight || element.clientHeight || 0;
    const renderedHeight = rect.height || 0;

    if (!layoutHeight || !renderedHeight || !Number.isFinite(renderedHeight)) {
        return 1;
    }

    const scaleY = renderedHeight / layoutHeight;
    return Number.isFinite(scaleY) && scaleY > 0 ? scaleY : 1;
}

function isDesktopFlashcardHeightTarget() {
    if (!document.body.classList.contains('active-question-flashcard')) return false;
    if (document.body.classList.contains('ipad-portrait-flashcard-layout')) return false;
    if (document.body.classList.contains('ipad-landscape-flashcard-layout')) return false;
    if (document.body.classList.contains('narrow-iphone-layout')) return false;

    return window.matchMedia?.('(min-width: 1025px) and (hover: hover) and (any-pointer: fine)').matches ?? false;
}

function getDesktopFlashcardHeightMode() {
    if (!isDesktopFlashcardHeightTarget()) return '';
    return document.body.classList.contains('fullscreen-mode') ? 'fullscreen' : 'normal';
}

function clearDesktopFullscreenFlashcardHeight() {
    document.querySelectorAll('.flashcard-container').forEach(container => {
        container.style.removeProperty('--flashcard-fixed-height');
    });
}

function updateDesktopFullscreenFlashcardHeight() {
    const flashcardContainer = document.getElementById('flashcardContainer') || document.querySelector('.flashcard-container');
    const heightMode = getDesktopFlashcardHeightMode();
    if (!flashcardContainer || !heightMode) {
        clearDesktopFullscreenFlashcardHeight();
        return;
    }

    const rect = flashcardContainer.getBoundingClientRect();
    const viewportHeight = window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight || 0;
    if (!viewportHeight || !Number.isFinite(rect.top)) return;

    // Phase 22GH/22GI: measure the space that truly remains below the card.
    // The app shell is transform-scaled on desktop, so convert rendered pixels back
    // into CSS layout pixels before assigning the flashcard height variable.
    // Normal mode keeps a larger reserve and lower cap than fullscreen so controls
    // stay visible and the card uses extra space without taking over the page.
    const bottomReserveRendered = heightMode === 'fullscreen' ? 28 : 72;
    const renderedAvailableHeight = Math.floor(viewportHeight - rect.top - bottomReserveRendered);
    const appShell = document.getElementById('app') || elements.questionContainer || flashcardContainer;
    const scaleY = getElementRenderedScaleY(appShell) || getElementRenderedScaleY(flashcardContainer) || 1;
    const cssAvailableHeight = Math.floor(renderedAvailableHeight / scaleY);

    if (!Number.isFinite(cssAvailableHeight) || cssAvailableHeight < 260) {
        flashcardContainer.style.removeProperty('--flashcard-fixed-height');
        return;
    }

    const maxHeight = heightMode === 'fullscreen' ? 640 : 540;
    const safeHeight = Math.min(maxHeight, cssAvailableHeight);
    flashcardContainer.style.setProperty('--flashcard-fixed-height', `${safeHeight}px`);
    fitFlashcardTextToFixedCard(flashcardContainer);
    queueFlashcardImageOverlaySync(flashcardContainer);
}

function queueDesktopFullscreenFlashcardHeightSync() {
    const queueState = state.desktopFullscreenFlashcardHeight;
    if (!queueState) return;

    if (queueState.rafId) {
        cancelAnimationFrame(queueState.rafId);
        queueState.rafId = 0;
    }

    queueState.timeoutIds.forEach(timeoutId => clearTimeout(timeoutId));
    queueState.timeoutIds = [];

    updateDesktopFullscreenFlashcardHeight();
    queueState.rafId = requestAnimationFrame(() => {
        queueState.rafId = 0;
        updateDesktopFullscreenFlashcardHeight();
        requestAnimationFrame(updateDesktopFullscreenFlashcardHeight);
    });

    [80, 220, 500].forEach(delay => {
        const timeoutId = setTimeout(updateDesktopFullscreenFlashcardHeight, delay);
        queueState.timeoutIds.push(timeoutId);
    });
}

function updateOptionsScrollCapacity() {
    const container = elements.optionsContainer;
    if (!container) return;

    if (!isOptionsScrollQuestionType() || container.style.display === 'none') {
        container.style.removeProperty('--study-options-scroll-max-height');
        return;
    }

    if (document.body.classList.contains('phone-landscape-mc-image-right-layout')) {
        updatePhoneLandscapeMultipleChoiceLayoutBounds();
        const parent = elements.questionContainer;
        const rect = container.getBoundingClientRect();
        const parentRect = parent?.getBoundingClientRect();
        if (parentRect && Number.isFinite(parentRect.bottom) && Number.isFinite(rect.top)) {
            const renderedAvailableHeight = Math.floor(parentRect.bottom - rect.top - 6);
            const scaleY = getElementRenderedScaleY(container);
            const cssAvailableHeight = Math.floor(renderedAvailableHeight / scaleY);
            if (Number.isFinite(cssAvailableHeight) && cssAvailableHeight > 0) {
                const safeHeight = Math.min(420, Math.max(1, cssAvailableHeight));
                container.style.setProperty('--study-options-scroll-max-height', `${safeHeight}px`);
                return;
            }
        }
    }

    const rect = container.getBoundingClientRect();
    const viewportHeight = window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight || 0;
    if (!viewportHeight || !Number.isFinite(rect.top)) return;

    const isFullscreen = document.body.classList.contains('fullscreen-mode');
    const bottomReserve = isFullscreen ? 30 : 54;
    const renderedAvailableHeight = Math.floor(viewportHeight - rect.top - bottomReserve);
    const scaleY = getElementRenderedScaleY(container);
    const cssAvailableHeight = Math.floor(renderedAvailableHeight / scaleY);
    const minimumHeight = isFullscreen ? 140 : 96;
    const safeHeight = Math.max(minimumHeight, Math.min(760, cssAvailableHeight));
    container.style.setProperty('--study-options-scroll-max-height', `${safeHeight}px`);
}

function updateOptionsScrollIndicators() {
    const container = elements.optionsContainer;
    if (!container) return;

    updateOptionsScrollCapacity();

    const isScrollableQuestion = isOptionsScrollQuestionType();
    const isVisible = container.style.display !== 'none' && !container.classList.contains('option-delay-active');
    const hasOverflow = isScrollableQuestion && isVisible && (container.scrollHeight - container.clientHeight > 2);
    const maxScrollTop = Math.max(0, container.scrollHeight - container.clientHeight);
    const scrollTop = container.scrollTop || 0;

    container.classList.toggle('options-overflow-y', hasOverflow);
    container.classList.toggle('options-can-scroll-up', hasOverflow && scrollTop > 2);
    container.classList.toggle('options-can-scroll-down', hasOverflow && scrollTop < maxScrollTop - 2);
}

function queueOptionsScrollIndicatorUpdate() {
    if (state.optionsScroll.rafId) {
        cancelAnimationFrame(state.optionsScroll.rafId);
        state.optionsScroll.rafId = 0;
    }

    state.optionsScroll.timeoutIds.forEach(timeoutId => clearTimeout(timeoutId));
    state.optionsScroll.timeoutIds = [];

    updateOptionsScrollIndicators();
    state.optionsScroll.rafId = requestAnimationFrame(() => {
        state.optionsScroll.rafId = 0;
        updateOptionsScrollIndicators();
        requestAnimationFrame(updateOptionsScrollIndicators);
    });

    [80, 220, 500].forEach(delay => {
        const timeoutId = setTimeout(updateOptionsScrollIndicators, delay);
        state.optionsScroll.timeoutIds.push(timeoutId);
    });
}

function setupOptionsScrollObservers() {
    const observedTargets = [
        elements.optionsContainer,
        elements.questionTextEl,
        elements.imageContainer,
        document.querySelector('.question-container')
    ].filter(Boolean);

    if ('ResizeObserver' in window && !state.optionsScroll.resizeObserver) {
        state.optionsScroll.resizeObserver = new ResizeObserver(queueOptionsScrollIndicatorUpdate);
        observedTargets.forEach(target => state.optionsScroll.resizeObserver.observe(target));
    }

    if ('MutationObserver' in window && elements.optionsContainer && !state.optionsScroll.mutationObserver) {
        state.optionsScroll.mutationObserver = new MutationObserver(queueOptionsScrollIndicatorUpdate);
        state.optionsScroll.mutationObserver.observe(elements.optionsContainer, {
            childList: true,
            characterData: true,
            subtree: true
        });
    }
}

function resetHiddenOptions() {
    elements.optionsContainer.querySelectorAll('.option-block.option-eliminated').forEach(block => {
        block.classList.remove('option-eliminated');
        block.style.display = '';
    });
    updateResetHiddenOptionsButton();
    queueOptionsScrollIndicatorUpdate();
}

function revealHiddenOptionsForFeedback() {
    resetHiddenOptions();
    elements.optionsContainer.querySelectorAll('.option-hide-btn').forEach(button => {
        button.disabled = true;
        button.classList.add('hidden');
    });
}

function handleHideOptionClick(event) {
    event.preventDefault();
    event.stopPropagation();
    if (state.questionAnswered || state.optionDelay.active) return;

    const block = event.currentTarget?.closest('.option-block');
    if (!block) return;
    const btn = block.querySelector('.optionBtn');
    const optionValue = normalizeSheetText(btn?.dataset.optionValue);
    if (isCurrentMultipleAnswerSubmitPending() && optionValue && state.multipleAnswerSelection?.has(optionValue)) {
        state.multipleAnswerSelection.delete(optionValue);
        btn?.classList.remove('option-selected');
        btn?.setAttribute('aria-pressed', 'false');
        updateMultipleAnswerSubmitAvailability();
    }
    block.classList.add('option-eliminated');
    block.style.display = 'none';
    updateResetHiddenOptionsButton();
    queueOptionsScrollIndicatorUpdate();
}



function isMultipleAnswerStudyQuestion(question = null) {
    const q = question || state.questionQueue[state.currentIndex] || null;
    return !!q && (q.type === 'multiple choice' || q.type === 'diagrams') && !!q.allowMultipleAnswers;
}

function getMultipleAnswerCorrectValues(question = {}) {
    const values = Array.isArray(question.correctAnswers) && question.correctAnswers.length
        ? question.correctAnswers
        : [question.correct];
    return values.map(value => normalizeSheetText(value)).filter(Boolean);
}

function isCurrentMultipleAnswerSubmitPending() {
    return isMultipleAnswerStudyQuestion() && !state.questionAnswered;
}

function updateMultipleAnswerSubmitAvailability() {
    if (!isCurrentMultipleAnswerSubmitPending()) return;
    updateNavigationButtons();
}

function toggleMultipleAnswerOption(button) {
    if (!button || state.questionAnswered || state.optionDelay.active) return;
    const optionValue = normalizeSheetText(button.dataset.optionValue);
    if (!optionValue) return;
    if (!(state.multipleAnswerSelection instanceof Set)) state.multipleAnswerSelection = new Set();
    if (state.multipleAnswerSelection.has(optionValue)) {
        state.multipleAnswerSelection.delete(optionValue);
        button.classList.remove('option-selected');
        button.setAttribute('aria-pressed', 'false');
    } else {
        state.multipleAnswerSelection.add(optionValue);
        button.classList.add('option-selected');
        button.setAttribute('aria-pressed', 'true');
    }
    updateMultipleAnswerSubmitAvailability();
}

function submitMultipleAnswerSelection() {
    if (isQuizFinished()) return;
    if (state.optionDelay.active) return;
    if (state.questionAnswered) return;
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
    if (isRetentionMode() && state.retentionAnswerLocked) return;

    const q = state.questionQueue[state.currentIndex];
    if (!isMultipleAnswerStudyQuestion(q)) return;
    const selectedValues = Array.from(state.multipleAnswerSelection || []).map(normalizeSheetText).filter(Boolean);
    if (!selectedValues.length) return;

    const correctValues = getMultipleAnswerCorrectValues(q);
    const correctSet = new Set(correctValues);
    const selectedSet = new Set(selectedValues);
    const isCorrect = correctSet.size === selectedSet.size && [...correctSet].every(value => selectedSet.has(value));
    const hideFeedback = isAnswerFeedbackHidden();

    state.questionAnswered = true;
    revealHiddenOptionsForFeedback();
    setOptionButtonsEnabled(false);

    elements.optionsContainer.querySelectorAll('.option-block').forEach((block, i) => {
        if (block.style.display === 'none') return;
        const btn = block.querySelector('.optionBtn');
        const explanationEl = block.querySelector('.explanation');
        const feedbackEl = block.querySelector('.option-feedback');
        if (!btn || !explanationEl || !feedbackEl) return;

        const optionValue = normalizeSheetText(btn.dataset.optionValue || btn.innerText);
        const isCorrectOption = correctSet.has(optionValue);
        const wasSelected = selectedSet.has(optionValue);
        btn.classList.remove('option-correct', 'option-incorrect', 'option-missed', 'option-selected');
        btn.setAttribute('aria-pressed', wasSelected ? 'true' : 'false');
        setMathChemFormattedText(explanationEl, hideFeedback ? '' : (btn.dataset.optionExplanation || ''));

        feedbackEl.classList.remove('correct-mark', 'incorrect-mark', 'missed-mark');
        if (!hideFeedback && isCorrectOption && wasSelected) {
            btn.classList.add('option-correct');
            feedbackEl.innerText = '✔';
            feedbackEl.classList.add('correct-mark');
        } else if (!hideFeedback && wasSelected && !isCorrectOption) {
            btn.classList.add('option-incorrect');
            feedbackEl.innerText = '✖';
            feedbackEl.classList.add('incorrect-mark');
        } else if (!hideFeedback && isCorrectOption && !wasSelected) {
            btn.classList.add('option-missed');
            feedbackEl.innerText = '!';
            feedbackEl.classList.add('missed-mark');
        } else {
            feedbackEl.innerText = '';
        }
    });

    queueOptionsScrollIndicatorUpdate();
    applyQuestionOutcome(q, isCorrect);

    if (isSpeedMode()) {
        setTimeout(nextQuestion, CONFIG.speedDelay);
    }
}

function handleNextButtonClick() {
    if (isCurrentMultipleAnswerSubmitPending()) {
        submitMultipleAnswerSelection();
        return;
    }
    nextQuestion();
}

function showMC(q) {
    const container = elements.optionsContainer;
    container.style.display = 'flex';

    let optionEntries = buildGlobalShuffleAnswerEntries(q, getMultipleChoiceOptionEntries(q));

    if (document.getElementById('shuffleAnswers').checked) {
        shuffleArray(optionEntries);
    }

    const blocks = ensureMultipleChoiceOptionBlocks(Math.max(optionEntries.length, 1));

    blocks.forEach((block, index) => {
        const btn = block.querySelector('.optionBtn');
        const exp = block.querySelector('.explanation');
        const fb = block.querySelector('.option-feedback');
        const entry = optionEntries[index] || null;

        block.classList.remove('option-eliminated');

        if (entry && btn && exp && fb) {
            const hideBtn = resetOptionFeedbackLane(block);
            if (hideBtn) {
                hideBtn.disabled = false;
                hideBtn.classList.remove('hidden');
                hideBtn.onclick = handleHideOptionClick;
            }
            const optionValue = entry.text || entry.image;
            block.style.display = '';
            btn.style.display = entry.image ? 'flex' : 'block';
            btn.innerHTML = '';
            if (entry.image) {
                const imageWrap = document.createElement('span');
                imageWrap.className = 'option-image-wrap';

                const image = document.createElement('img');
                image.className = 'option-image';
                image.alt = entry.text ? `Image for ${entry.text}` : `Option ${index + 1} image`;
                image.addEventListener('load', queueOptionsScrollIndicatorUpdate, { once: true });
                image.addEventListener('error', queueOptionsScrollIndicatorUpdate, { once: true });
                image.src = entry.image;

                imageWrap.appendChild(image);
                imageWrap.appendChild(createOptionImageZoomButton(entry.image, image.alt));
                btn.appendChild(imageWrap);
            }
            if (entry.text) {
                const textEl = document.createElement('span');
                textEl.className = 'option-text';
                setMathChemFormattedText(textEl, entry.text);
                btn.appendChild(textEl);
            }
            btn.dataset.optionValue = optionValue;
            btn.dataset.optionExplanation = entry.explanation || '';
            btn.disabled = false;
            btn.style.pointerEvents = 'auto';
            btn.style.opacity = '1';
            btn.classList.toggle('option-has-image', !!entry.image);
            btn.classList.remove('option-correct', 'option-incorrect', 'option-missed', 'option-selected');
            btn.setAttribute('aria-pressed', 'false');
            btn.onclick = () => {
                if (isMultipleAnswerStudyQuestion(q)) {
                    toggleMultipleAnswerOption(btn);
                    return;
                }
                checkAnswer(optionValue, optionEntries.map(item => item.explanation));
            };
            exp.innerText = '';
            const activeHideBtn = resetOptionFeedbackLane(block);
            if (activeHideBtn) {
                activeHideBtn.disabled = false;
                activeHideBtn.classList.remove('hidden');
                activeHideBtn.onclick = handleHideOptionClick;
            }
        } else {
            block.style.display = 'none';
            if (btn) {
                btn.style.display = 'none';
                btn.innerText = '';
                btn.dataset.optionValue = '';
                btn.dataset.optionExplanation = '';
                btn.classList.remove('option-correct', 'option-incorrect', 'option-missed', 'option-selected', 'option-has-image');
                btn.removeAttribute('aria-pressed');
                btn.onclick = null;
            }
            if (exp) exp.innerText = '';
            if (fb) {
                fb.innerText = '';
                fb.classList.remove('correct-mark', 'incorrect-mark', 'missed-mark');
            }
            const hideBtn = ensureOptionHideControl(block);
            if (hideBtn) {
                hideBtn.onclick = null;
                hideBtn.disabled = true;
                hideBtn.classList.add('hidden');
            }
        }
    });

    updateResetHiddenOptionsButton();
    startOptionDelayForCurrentQuestion(q);
    queueOptionsScrollIndicatorUpdate();
}

// ================= WRONG ANSWER LOGIC =================
function handleWrongAnswer() {
    const q = state.questionQueue[state.currentIndex];

    if (isRetentionMode()) {
        state.retentionSolvedIds.delete(q.id);
        state.pendingRetentionJump = true;
        state.pendingRetentionCorrect = false;
        state.retentionAnswerLocked = true;
        return;
    }

    if (isRetryMode()) {
        const tetherBounds = getTetherRunBoundsInQueue(state.questionQueue, state.currentIndex);
        const shouldMoveTetherRun = isTetherBuildUpEnabled()
            && tetherBounds.key
            && tetherBounds.end > tetherBounds.start;

        const moveStart = shouldMoveTetherRun ? tetherBounds.start : state.currentIndex;
        const moveCount = shouldMoveTetherRun ? (tetherBounds.end - tetherBounds.start + 1) : 1;
        const movingQuestions = state.questionQueue.splice(moveStart, moveCount);

        let insertIndex = moveStart + 3;
        if (insertIndex > state.questionQueue.length) {
            insertIndex = state.questionQueue.length;
        }

        state.questionQueue.splice(insertIndex, 0, ...movingQuestions);
        state.currentIndex = Math.min(moveStart, Math.max(0, state.questionQueue.length - 1));
        state.pendingMasteryAdvance = true;
        return;
    }

    if (isMasteryCheckMode()) {
        state.masteryCheckPendingJump = true;
        state.masteryCheckPendingAdvance = false;
        state.masteryCheckPendingCheckpointComplete = false;
        return;
    }
}

// ================= CORRECT ANSWER LOGIC =================
function handleCorrectAnswer() {
    const q = state.questionQueue[state.currentIndex];

    if (isRetentionMode()) {
        state.retentionSolvedIds.add(q.id);
        state.pendingRetentionCorrect = true;
        state.pendingRetentionJump = false;
        state.retentionAnswerLocked = true;
        return;
    }

    if (isRetryMode()) {
        const tetherBounds = getTetherRunBoundsInQueue(state.questionQueue, state.currentIndex);
        const shouldKeepTetherRun = isTetherBuildUpEnabled()
            && tetherBounds.key
            && tetherBounds.end > tetherBounds.start;

        if (shouldKeepTetherRun && state.currentIndex < tetherBounds.end) {
            state.currentIndex += 1;
            state.pendingMasteryAdvance = true;
            return;
        }

        if (shouldKeepTetherRun) {
            state.questionQueue.splice(tetherBounds.start, tetherBounds.end - tetherBounds.start + 1);
            state.currentIndex = Math.min(tetherBounds.start, Math.max(0, state.questionQueue.length - 1));
        } else {
            state.questionQueue.splice(state.currentIndex, 1);

            if (state.questionQueue.length === 0) {
                state.currentIndex = 0;
            }
        }

        state.pendingMasteryAdvance = true;
        return;
    }

    if (isMasteryCheckMode()) {
        state.masteryCheckPendingJump = false;

        if (state.masteryCheckInCheckpoint) {
            state.masteryCheckCheckpointSolvedIds.add(q.id);

            if (state.masteryCheckCheckpointSolvedIds.size === state.questionQueue.length) {
                state.masteryCheckPendingCheckpointComplete = true;
                state.masteryCheckPendingAdvance = false;
            } else {
                state.masteryCheckPendingAdvance = true;
            }

            return;
        }

        addMasteryCheckSegmentQuestionsWithTether(q);

        const atCheckpointBoundary = state.masteryCheckSegmentQuestions.length >= 10;
        const atEndOfRemainingPool = state.currentIndex >= state.questionQueue.length - 1;
        const canStartCheckpointWithoutSplittingString = isAtEndOfTetherBuildUpRun(state.questionQueue, state.currentIndex);

        if ((atCheckpointBoundary && canStartCheckpointWithoutSplittingString) || (atEndOfRemainingPool && state.masteryCheckSegmentQuestions.length > 0)) {
            state.masteryCheckPendingCheckpointStart = true;
            state.masteryCheckPendingAdvance = false;
        } else {
            state.masteryCheckPendingAdvance = true;
        }

        return;
    }
}

// ================= ANSWER =================
function checkAnswer(selected, explanations) {
    if (isQuizFinished()) return;
    if (state.optionDelay.active) return;
    if (state.questionAnswered) return;
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
    if (isRetentionMode() && state.retentionAnswerLocked) return;

    state.questionAnswered = true;
    revealHiddenOptionsForFeedback();
    setOptionButtonsEnabled(false);

    const q = state.questionQueue[state.currentIndex];
    const isCorrect = selected === q.correct;
    const hideFeedback = isAnswerFeedbackHidden();

    elements.optionsContainer.querySelectorAll('.option-block').forEach((block, i) => {
        if (block.style.display === 'none') return;
        const btn = block.querySelector('.optionBtn');
        const explanationEl = block.querySelector('.explanation');
        const feedbackEl = block.querySelector('.option-feedback');
        if (!btn || !explanationEl || !feedbackEl) return;

        btn.classList.remove('option-correct', 'option-incorrect', 'option-missed');
        setMathChemFormattedText(explanationEl, hideFeedback ? '' : (explanations[i] || ''));
        const optionValue = btn.dataset.optionValue || btn.innerText;

        if (!hideFeedback) {
            if (optionValue === q.correct) {
                btn.classList.add('option-correct');
            } else if (optionValue === selected && !isCorrect) {
                btn.classList.add('option-incorrect');
            }
        }

        feedbackEl.classList.remove('correct-mark', 'incorrect-mark', 'missed-mark');

        if (!hideFeedback && optionValue === q.correct) {
            feedbackEl.innerText = '✔';
            feedbackEl.classList.add('correct-mark');
        } else if (!hideFeedback && optionValue === selected && !isCorrect) {
            feedbackEl.innerText = '✖';
            feedbackEl.classList.add('incorrect-mark');
        } else {
            feedbackEl.innerText = '';
        }
    });

    queueOptionsScrollIndicatorUpdate();
    applyQuestionOutcome(q, isCorrect);

    if (isSpeedMode()) {
        setTimeout(nextQuestion, CONFIG.speedDelay);
    }
}

// ================= FLASHCARDS =================
async function ensureFlashcardQuestionImagesLoaded(question = {}) {
    if (!question || !question.flashcardImagesDeferred) return false;
    const sourceQuestionId = normalizeSheetText(question.sourceQuestionId);
    if (!sourceQuestionId) {
        question.flashcardImagesDeferred = false;
        return false;
    }
    try {
        const detail = await loadFlashcardImageDetailByQuestionId(sourceQuestionId);
        question.termImage = question.termImageKnownAbsent ? '' : normalizeSheetText(detail?.term_image_url);
        question.definitionImage = question.definitionImageKnownAbsent ? '' : normalizeSheetText(detail?.definition_image_url);
        question.flashcardImagesDeferred = false;
        return !!(question.termImage || question.definitionImage);
    } catch (error) {
        console.error('Could not lazy-load flashcard images:', error);
        question.flashcardImagesDeferred = false;
        return false;
    }
}

function queueFlashcardLazyImageHydration(question = {}) {
    if (!question?.flashcardImagesDeferred) return;
    ensureFlashcardQuestionImagesLoaded(question).then(updated => {
        if (!updated) return;
        if (state.questionQueue[state.currentIndex] !== question) return;
        if (state.questionAnswered || isQuizFinished()) return;
        showQuestion();
    });
}

function getFlashcardSideData(q, side) {
    if (side === 'definition') {
        return {
            sideName: 'Definition',
            text: normalizeSheetText(q.definitionText),
            html: normalizeSheetText(q.definitionHtml),
            imageUrl: normalizeSheetText(q.definitionImage),
            imageLabels: normalizeDiagramLabels(q.definitionImageLabels || []),
            imageDrawStrokes: cloneImageEditorDrawStrokes(q.definitionImageDrawStrokes || []),
            labelDisplayMode: 'normal'
        };
    }

    return {
        sideName: 'Term',
        text: normalizeSheetText(q.termText),
        html: normalizeSheetText(q.termHtml),
        imageUrl: normalizeSheetText(q.termImage),
        imageLabels: normalizeDiagramLabels(q.termImageLabels || []),
        imageDrawStrokes: cloneImageEditorDrawStrokes(q.termImageDrawStrokes || []),
        labelDisplayMode: 'normal'
    };
}

function flashcardSideHasUserContent(sideData = {}) {
    const safeHtml = sanitizeLearningResourcesHtml(sideData.html || '');
    return !!(htmlToDisplayText(safeHtml) || normalizeSheetText(sideData.text) || normalizeSheetText(sideData.imageUrl));
}

function getFlashcardSideImageLabelsForMode(labels = [], mode = 'normal') {
    if (mode === 'numbers') return getNumberedFlashcardImageLabels(labels);
    if (mode === 'answers') return getAnswerFlashcardImageLabels(labels);
    return normalizeDiagramLabels(labels || []);
}

function buildFlashcardGeneratedLabelAnswerSide(frontSide = {}) {
    const labels = normalizeDiagramLabels(frontSide.imageLabels || []);
    return {
        sideName: 'Label Answers',
        text: '',
        html: '',
        imageUrl: normalizeSheetText(frontSide.imageUrl),
        imageLabels: labels,
        imageDrawStrokes: cloneImageEditorDrawStrokes(frontSide.imageDrawStrokes || []),
        labelDisplayMode: 'answers',
        generatedLabelAnswerSide: true,
        labelAnswerLabels: labels
    };
}

function toggleFlashcardFlip() {
    if (state.learningResourcesOverlayOpen) return;
    if (state.flashcardImageZoomOpen) return;
    if (state.questionAnswered) return;

    state.flashcardFlipped = !state.flashcardFlipped;

    const card = document.getElementById('flashcardCard');
    if (card) {
        card.classList.toggle('is-flipped', state.flashcardFlipped);
        queueFlashcardImageOverlaySync(card);
        setTimeout(() => queueFlashcardImageOverlaySync(card), 520);
    }
}

function buildFlashcardFace(sideData, faceClass) {
    const face = document.createElement('div');
    face.className = `flashcard-face ${faceClass}`;

    const content = document.createElement('div');
    content.className = 'flashcard-side-content';

    const safeHtml = sanitizeLearningResourcesHtml(sideData.html || '');
    const imageLabels = normalizeDiagramLabels(sideData.imageLabels || []);
    const imageDrawStrokes = cloneImageEditorDrawStrokes(sideData.imageDrawStrokes || []);
    const hasGeneratedLabelAnswers = !!(sideData.generatedLabelAnswerSide && imageLabels.length);
    const hasRichText = !!htmlToDisplayText(safeHtml);
    const hasText = hasGeneratedLabelAnswers || hasRichText || !!sideData.text;
    const hasImage = !!sideData.imageUrl;
    const displayImageLabels = getFlashcardSideImageLabelsForMode(imageLabels, sideData.labelDisplayMode || 'normal');

    if (hasText && hasImage) {
        content.classList.add('split');
    } else if (hasText) {
        content.classList.add('text-only');
    } else if (hasImage) {
        content.classList.add('image-only');
    } else {
        content.classList.add('text-only');
    }

    if (hasText) {
        const text = document.createElement('div');
        text.className = 'flashcard-side-text';
        if (hasGeneratedLabelAnswers) {
            text.innerHTML = buildFlashcardLabelAnswerHtml(sideData.labelAnswerLabels || imageLabels);
        } else if (hasRichText) {
            text.innerHTML = safeHtml;
        } else {
            text.innerText = sideData.text;
        }
        content.appendChild(text);
    }

    if (hasImage) {
        const imageWrap = document.createElement('div');
        imageWrap.className = 'flashcard-side-image-wrap';

        const img = document.createElement('img');
        img.className = 'flashcard-side-image';
        img.alt = `${sideData.sideName} image`;
        setImageElementSourceWithMediaResolution(img, sideData.imageUrl, {
            onLoad: () => {
                queueFlashcardImageOverlaySync(face);
                renderFlashcardStudyStrokeLayer(imageFrame);
            }
        });

        const zoomBtn = document.createElement('button');
        zoomBtn.type = 'button';
        zoomBtn.className = 'flashcard-image-zoom-btn';
        zoomBtn.setAttribute('aria-label', 'Zoom image');
        zoomBtn.setAttribute('title', 'Zoom image');
        zoomBtn.innerText = '⤢';

        zoomBtn.addEventListener('pointerdown', e => {
            e.stopPropagation();
        });

        zoomBtn.addEventListener('pointerup', e => {
            e.stopPropagation();
        });

        zoomBtn.addEventListener('click', e => {
            e.preventDefault();
            e.stopPropagation();
            const currentSource = normalizeSheetText(img.dataset.resolvedMediaUrl || img.currentSrc || img.src || sideData.imageUrl);
            if (isSupabaseMediaReference(currentSource)) {
                resolveSupabaseMediaValue(currentSource).then(resolvedUrl => {
                    if (resolvedUrl) openFlashcardImageOverlay(resolvedUrl, `${sideData.sideName} image`, { diagramLabels: displayImageLabels, imageDrawStrokes });
                }).catch(error => console.error('Could not resolve flashcard zoom image:', error));
                return;
            }
            openFlashcardImageOverlay(currentSource, `${sideData.sideName} image`, { diagramLabels: displayImageLabels, imageDrawStrokes });
        });

        const imageFrame = document.createElement('div');
        imageFrame.className = 'flashcard-side-image-frame';
        imageFrame.__flashcardImageDrawStrokes = imageDrawStrokes;
        imageFrame.dataset.visibleStrokeLabels = '';
        imageFrame.appendChild(img);
        if (imageDrawStrokes.length) {
            const strokeCanvas = document.createElement('canvas');
            strokeCanvas.className = 'flashcard-side-image-stroke-layer';
            strokeCanvas.setAttribute('aria-hidden', 'true');
            imageFrame.appendChild(strokeCanvas);
        }
        if (displayImageLabels.length) {
            const labelLayer = document.createElement('div');
            labelLayer.className = 'flashcard-side-image-label-layer diagram-study-label-layer';
            labelLayer.setAttribute('aria-hidden', 'false');
            labelLayer.innerHTML = displayImageLabels.map((item, index) => `<button type="button" class="diagram-study-label flashcard-study-label-toggle" data-flashcard-label-toggle="${index}" style="left:${item.x}%; top:${item.y}%" aria-pressed="false">${renderMathChemTextToHtml(item.label)}</button>`).join('');
            imageFrame.appendChild(labelLayer);
        }
        imageFrame.appendChild(zoomBtn);

        imageWrap.appendChild(imageFrame);
        content.appendChild(imageWrap);
        renderFlashcardStudyStrokeLayer(imageFrame);
        syncFlashcardStudyStrokeToggleButtons(face);
        queueFlashcardImageOverlaySync(face);
    }

    if (!hasText && !hasImage) {
        const empty = document.createElement('div');
        empty.className = 'flashcard-placeholder';
        empty.innerText = 'No content on this side.';
        content.appendChild(empty);
    }

    face.appendChild(content);

    // Phase 22KV guardrail: label/answer buttons own stroke visibility on that side.
    // This preserves the established display rules (front = numbers, back = names)
    // while preventing the card tap/flip handler from swallowing back-side answer clicks.
    face.addEventListener('click', event => {
        if (!event.target?.closest?.('[data-flashcard-label-toggle]')) return;
        event.preventDefault();
        event.stopPropagation();
        toggleFlashcardStudyStrokeLabel(event.target);
    });
    face.addEventListener('pointerdown', event => {
        if (event.target?.closest?.('[data-flashcard-label-toggle]')) event.stopPropagation();
    });
    face.addEventListener('pointerup', event => {
        if (event.target?.closest?.('[data-flashcard-label-toggle]')) event.stopPropagation();
    });

    return face;
}

function syncFlashcardImageFrameOverlayBounds(frame) {
    if (!frame) return;
    const img = frame.querySelector('.flashcard-side-image');
    const labelLayer = frame.querySelector('.flashcard-side-image-label-layer');
    const zoomBtn = frame.querySelector('.flashcard-image-zoom-btn');
    const imageWrap = frame.closest('.flashcard-side-image-wrap');
    if (!img || !imageWrap) return;
    if (!img.complete || !img.naturalWidth || !img.naturalHeight) return;

    applyImageStageSize(frame, img, imageWrap);

    // Phase 22GD: the image frame itself is now the coordinate stage. Labels use
    // their saved percentage positions against this stage in normal, fullscreen,
    // flipped, and rotated layouts, so no left/top/width/height offset is needed.
    frame.style.removeProperty('--flashcard-image-visual-left');
    frame.style.removeProperty('--flashcard-image-visual-top');
    frame.style.removeProperty('--flashcard-image-visual-width');
    frame.style.removeProperty('--flashcard-image-visual-height');
    clearStageLabelLayerOffsets(labelLayer);

    if (zoomBtn) {
        // Keep the zoom button under CSS control; do not write inline positions here.
        zoomBtn.style.removeProperty('left');
        zoomBtn.style.removeProperty('top');
        zoomBtn.style.removeProperty('right');
    }
}

function syncFlashcardImageOverlayBounds(root = document) {
    const scope = root?.querySelectorAll ? root : document;
    const frames = Array.from(scope.querySelectorAll('.flashcard-side-image-frame'));
    frames.forEach(syncFlashcardImageFrameOverlayBounds);
}

function queueFlashcardImageOverlaySync(root = document) {
    requestAnimationFrame(() => {
        syncFlashcardImageOverlayBounds(root);
        setTimeout(() => syncFlashcardImageOverlayBounds(root), 80);
        setTimeout(() => syncFlashcardImageOverlayBounds(root), 240);
    });
}

function resetFlashcardImageFrameResizeObserver() {
    if (state.flashcardImageFrameResizeObserver) {
        state.flashcardImageFrameResizeObserver.disconnect();
    }
}

function observeFlashcardImageFrames(root = document) {
    if (!('ResizeObserver' in window)) return;
    const scope = root?.querySelectorAll ? root : document;
    const frames = Array.from(scope.querySelectorAll('.flashcard-side-image-frame'));
    if (!frames.length) return;

    if (!state.flashcardImageFrameResizeObserver) {
        state.flashcardImageFrameResizeObserver = new ResizeObserver(entries => {
            entries.forEach(entry => {
                const target = entry.target;
                const frame = target?.classList?.contains('flashcard-side-image-frame')
                    ? target
                    : target?.querySelector?.('.flashcard-side-image-frame');
                syncFlashcardImageFrameOverlayBounds(frame);
            });
            queueFlashcardZoomOverlayLabelSync();
        });
    }

    const targets = new Set();
    frames.forEach(frame => {
        targets.add(frame);
        const imageWrap = frame.closest('.flashcard-side-image-wrap');
        if (imageWrap) targets.add(imageWrap);
    });
    targets.forEach(target => state.flashcardImageFrameResizeObserver.observe(target));
}

function fitFlashcardTextToFixedCard(root = document) {
    const textNodes = Array.from(root.querySelectorAll?.('.flashcard-side-text') || []);
    if (!textNodes.length) return;

    const fitOne = textEl => {
        const content = textEl.closest('.flashcard-side-content');
        if (!content) return;
        textEl.style.removeProperty('--flashcard-fitted-font-size');
        const baseFontSize = parseFloat(window.getComputedStyle(textEl).fontSize) || 24;
        const isSplitLayout = content.classList.contains('split');
        const textRect = textEl.getBoundingClientRect();
        const contentRect = content.getBoundingClientRect();
        const maxWidth = Math.max(1, (isSplitLayout ? textRect.width : contentRect.width) - 4);
        const maxHeight = Math.max(1, (isSplitLayout ? textRect.height : contentRect.height) - 4);
        if (!maxWidth || !maxHeight) return;

        let low = 0.52;
        let high = 1;
        let best = 1;
        for (let i = 0; i < 8; i += 1) {
            const mid = (low + high) / 2;
            textEl.style.setProperty('--flashcard-fitted-font-size', `${Math.max(11, baseFontSize * mid).toFixed(2)}px`);
            const fits = textEl.scrollWidth <= maxWidth + 2 && textEl.scrollHeight <= maxHeight + 2;
            if (fits) {
                best = mid;
                low = mid;
            } else {
                high = mid;
            }
        }
        textEl.style.setProperty('--flashcard-fitted-font-size', `${Math.max(11, baseFontSize * best).toFixed(2)}px`);
    };

    requestAnimationFrame(() => {
        textNodes.forEach(fitOne);
        // Phase 22GF: adaptive text/image sizing can change the image wrapper after
        // font fitting, so resync the image stage after the text takes its final space.
        queueFlashcardImageOverlaySync(root);
    });
}

function enableFlashcardGesture(card, onKnow, onDontKnow) {
    let tracking = false;
    let startX = 0;
    let startY = 0;
    let activePointerId = null;
    let angledTouchSwipe = false;

    const clampSwipeValue = (value, min, max) => Math.max(min, Math.min(max, value));

    function isAngledTouchFlashcardSwipeEvent(event) {
        return event?.pointerType === 'touch' && isAppleTouchStudyDevice();
    }

    function isFlashcardGestureBlockedTarget(target) {
        if (!target || !target.closest) return false;
        return !!target.closest([
            'button',
            'input',
            'select',
            'textarea',
            'a',
            '[contenteditable="true"]',
            '.flashcard-image-zoom-btn',
            '.flashcard-study-label-toggle',
            '#flashcardImageOverlay'
        ].join(','));
    }

    function clearSwipeBorderState() {
        card.classList.remove('swiping-know', 'swiping-dont-know');
    }

    function setSwipeBorderState(kind) {
        clearSwipeBorderState();
        if (kind === 'know') {
            card.classList.add('swiping-know');
        } else if (kind === 'dont-know') {
            card.classList.add('swiping-dont-know');
        }
    }

    function resetCardPosition() {
        card.style.transition = 'transform 0.18s ease';
        card.style.transform = '';
        clearSwipeBorderState();
    }

    function endTracking() {
        tracking = false;
        activePointerId = null;
        angledTouchSwipe = false;
    }

    function finishInteraction(e, cancelled = false) {
        if (!tracking) return;
        if (activePointerId !== null && e.pointerId !== activePointerId) return;

        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        const absX = Math.abs(dx);
        const absY = Math.abs(dy);
        const isTap = absX < 10 && absY < 10;
        const isSwipe = angledTouchSwipe
            ? absX >= 64 && absX >= absY * 0.65
            : absX >= 70 && absX > absY * 1.2;

        try {
            if (card.hasPointerCapture(e.pointerId)) {
                card.releasePointerCapture(e.pointerId);
            }
        } catch (err) {
            // ignore pointer capture release failures
        }

        endTracking();
        resetCardPosition();

        if (cancelled || state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen || state.questionAnswered) {
            clearFlashcardSwipeFeedback();
            clearSwipeBorderState();
            return;
        }

        if (isSwipe) {
            setSwipeBorderState(dx > 0 ? 'know' : 'dont-know');
            setFlashcardSwipeFeedback(dx > 0 ? 'know' : 'dont-know');
            setTimeout(() => {
                if (dx > 0) {
                    onKnow();
                } else {
                    onDontKnow();
                }
            }, 90);
            return;
        }

        clearFlashcardSwipeFeedback();

        if (isTap) {
            toggleFlashcardFlip();
        }
    }

    card.addEventListener('pointerdown', e => {
        if (state.learningResourcesOverlayOpen) return;
        if (state.flashcardImageZoomOpen) return;
        if (state.questionAnswered) return;
        if (e.button !== undefined && e.button !== 0) return;
        if (isFlashcardGestureBlockedTarget(e.target)) return;

        tracking = true;
        startX = e.clientX;
        startY = e.clientY;
        activePointerId = e.pointerId;
        angledTouchSwipe = isAngledTouchFlashcardSwipeEvent(e);
        card.style.transition = 'none';
        clearFlashcardSwipeFeedback();
        clearSwipeBorderState();

        try {
            card.setPointerCapture(e.pointerId);
        } catch (err) {
            // ignore pointer capture failures
        }
    });

    card.addEventListener('pointermove', e => {
        if (!tracking) return;
        if (activePointerId !== null && e.pointerId !== activePointerId) return;
        if (state.questionAnswered) return;

        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        const absX = Math.abs(dx);
        const absY = Math.abs(dy);

        if (angledTouchSwipe) {
            if (absX > 6 || absY > 6) {
                e.preventDefault();
            }

            const limitedDx = clampSwipeValue(dx * 0.68, -132, 132);
            const limitedDy = clampSwipeValue(dy * 0.34, -56, 56);
            const rotation = clampSwipeValue(dx * 0.035, -8, 8);
            card.style.transform = `translate(${limitedDx}px, ${limitedDy}px) rotate(${rotation}deg)`;

            if (absX >= 20 && absX >= absY * 0.65) {
                const swipeKind = dx > 0 ? 'know' : 'dont-know';
                setSwipeBorderState(swipeKind);
                setFlashcardSwipeFeedback(swipeKind);
            } else {
                clearSwipeBorderState();
                clearFlashcardSwipeFeedback();
            }
            return;
        }

        if (absX > absY) {
            e.preventDefault();
        }

        const limitedDx = Math.max(-52, Math.min(52, dx * 0.24));
        card.style.transform = `translateX(${limitedDx}px)`;

        if (absX >= 18 && absX > absY) {
            const swipeKind = dx > 0 ? 'know' : 'dont-know';
            setSwipeBorderState(swipeKind);
            setFlashcardSwipeFeedback(swipeKind);
        } else {
            clearSwipeBorderState();
            clearFlashcardSwipeFeedback();
        }
    }, { passive: false });

    card.addEventListener('pointerup', e => finishInteraction(e));
    card.addEventListener('pointercancel', e => finishInteraction(e, true));
}

function gradeFlashcard(knewIt) {
    if (isQuizFinished()) return;
    if (state.questionAnswered) return;
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
    if (isRetentionMode() && state.retentionAnswerLocked) return;

    const q = state.questionQueue[state.currentIndex];
    state.questionAnswered = true;
    setFlashcardInteractionEnabled(false);
    applyQuestionOutcome(q, knewIt);
    nextQuestion();
}

function showFlashcard(q) {
    state.flashcardGradeFeedbackPending = false;
    resetFlashcardImageFrameResizeObserver();

    const frontSide = state.flashcardFrontMode === 'term'
        ? getFlashcardSideData(q, 'term')
        : getFlashcardSideData(q, 'definition');

    let backSide = state.flashcardFrontMode === 'term'
        ? getFlashcardSideData(q, 'definition')
        : getFlashcardSideData(q, 'term');

    if (normalizeDiagramLabels(frontSide.imageLabels || []).length) {
        frontSide.labelDisplayMode = 'numbers';
        if (!flashcardSideHasUserContent(backSide)) {
            backSide = buildFlashcardGeneratedLabelAnswerSide(frontSide);
        }
    }
    // Phase 22KV guardrail: only the front side uses number-only labels.
    // The flipped/back side preserves the established answer/name label text behavior,
    // and clicking those names toggles that label's draw strokes instead of flipping the card.

    const container = document.createElement('div');
    container.id = 'flashcardContainer';
    container.className = 'flashcard-container';

    const card = document.createElement('div');
    card.id = 'flashcardCard';
    card.className = 'flashcard-card';
    if (state.flashcardFlipped) {
        card.classList.add('is-flipped');
    }
    mountQuestionStarButtonBesideStudyMenu();

    const cardInner = document.createElement('div');
    cardInner.className = 'flashcard-card-inner';

    cardInner.appendChild(buildFlashcardFace(frontSide, 'front'));
    cardInner.appendChild(buildFlashcardFace(backSide, 'back'));
    cardInner.addEventListener('click', event => {
        if (!event.target?.closest?.('[data-flashcard-label-toggle]')) return;
        event.preventDefault();
        event.stopPropagation();
        toggleFlashcardStudyStrokeLabel(event.target);
    });
    cardInner.addEventListener('pointerdown', event => {
        if (event.target?.closest?.('[data-flashcard-label-toggle]')) event.stopPropagation();
    });
    cardInner.addEventListener('pointerup', event => {
        if (event.target?.closest?.('[data-flashcard-label-toggle]')) event.stopPropagation();
    });
    cardInner.addEventListener('transitionend', event => {
        if (event.propertyName === 'transform') {
            queueFlashcardImageOverlaySync(card);
        }
    });
    card.appendChild(cardInner);
    container.appendChild(card);
    const swipeFeedback = document.createElement('div');
    swipeFeedback.id = 'flashcardSwipeFeedback';
    swipeFeedback.className = 'flashcard-swipe-feedback';
    container.appendChild(swipeFeedback);

    const gradeRow = document.createElement('div');
    gradeRow.id = 'flashcardGradeRow';
    gradeRow.className = 'flashcard-grade-row';

    const didntKnowBtn = document.createElement('button');
    didntKnowBtn.type = 'button';
    didntKnowBtn.className = 'flashcard-grade-btn wrong flashcard-side-btn left';
    didntKnowBtn.innerText = '✖';
    didntKnowBtn.onclick = () => gradeFlashcard(false);

    const knowBtn = document.createElement('button');
    knowBtn.type = 'button';
    knowBtn.className = 'flashcard-grade-btn correct flashcard-side-btn right';
    knowBtn.innerText = '✔';
    knowBtn.onclick = () => gradeFlashcard(true);

    gradeRow.appendChild(didntKnowBtn);
    gradeRow.appendChild(knowBtn);
    container.appendChild(gradeRow);

    elements.questionContainer.appendChild(container);

    queueFlashcardLazyImageHydration(q);
    enableFlashcardGesture(card, () => gradeFlashcard(true), () => gradeFlashcard(false));
    setFlashcardInteractionEnabled(true);
    queueDesktopFullscreenFlashcardHeightSync();
    fitFlashcardTextToFixedCard(container);
    observeFlashcardImageFrames(container);
    queueFlashcardImageOverlaySync(container);
}

// ================= HIERARCHY DRAG =================
function enableHierarchyDrag(container) {
    let draggedRow = null;
    let placeholder = null;
    let dragOffsetY = 0;
    let dragStartX = 0;
    let dragStartY = 0;
    let dragging = false;

    function clearDropIndicators() {
        Array.from(container.children).forEach(row => {
            row.style.borderTop = '';
            row.style.borderBottom = '';
        });
        if (placeholder) {
            placeholder.style.background = 'rgba(124,108,255,0.18)';
            placeholder.style.border = '2px dashed #7c6cff';
        }
    }

    function finishDrag() {
        if (!draggedRow) return;

        window.removeEventListener('pointermove', onPointerMove);
        window.removeEventListener('pointerup', onPointerUp);
        window.removeEventListener('pointercancel', onPointerUp);

        clearDropIndicators();

        if (placeholder && placeholder.parentNode === container) {
            container.replaceChild(draggedRow, placeholder);
        }

        draggedRow.style.position = '';
        draggedRow.style.left = '';
        draggedRow.style.top = '';
        draggedRow.style.width = '';
        draggedRow.style.zIndex = '';
        draggedRow.style.pointerEvents = '';
        draggedRow.style.opacity = '';
        draggedRow.style.transform = '';
        draggedRow.style.boxShadow = '';
        draggedRow.style.cursor = 'default';

        draggedRow = null;
        placeholder = null;
        dragging = false;
    }

    function onPointerMove(e) {
        if (!draggedRow) return;

        if (!dragging) {
            const movedEnough = Math.abs(e.clientY - dragStartY) > 4 || Math.abs(e.clientX - dragStartX) > 4;
            if (!movedEnough) return;
            dragging = true;
        }

        e.preventDefault();

        draggedRow.style.top = `${e.clientY - dragOffsetY}px`;
        draggedRow.style.left = `${container.getBoundingClientRect().left}px`;

        clearDropIndicators();

        const rows = Array.from(container.children).filter(row => row !== placeholder);

        if (rows.length === 0) {
            container.appendChild(placeholder);
            return;
        }

        let placed = false;

        for (const row of rows) {
            const rect = row.getBoundingClientRect();
            const midpoint = rect.top + rect.height / 2;

            if (e.clientY < midpoint) {
                row.style.borderTop = '3px solid #7c6cff';
                container.insertBefore(placeholder, row);
                placed = true;
                break;
            }
        }

        if (!placed) {
            const lastRow = rows[rows.length - 1];
            lastRow.style.borderBottom = '3px solid #7c6cff';
            container.appendChild(placeholder);
        }
    }

    function onPointerUp() {
        finishDrag();
    }

    container.querySelectorAll('.hierarchy-item').forEach(item => {
        item.addEventListener('pointerdown', e => {
            if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
            if (item.dataset.dragDisabled === 'true') return;
            if (state.questionAnswered) return;
            if (e.button !== undefined && e.button !== 0) return;

            const row = item.closest('.hierarchy-row');
            if (!row) return;

            e.preventDefault();

            draggedRow = row;
            dragging = false;
            dragStartX = e.clientX;
            dragStartY = e.clientY;

            const rowRect = row.getBoundingClientRect();
            dragOffsetY = e.clientY - rowRect.top;

            placeholder = document.createElement('div');
            placeholder.className = 'hierarchy-placeholder';
            placeholder.style.height = `${rowRect.height}px`;
            placeholder.style.border = '2px dashed #7c6cff';
            placeholder.style.borderRadius = '8px';
            placeholder.style.background = 'rgba(124,108,255,0.18)';
            placeholder.style.boxSizing = 'border-box';

            container.replaceChild(placeholder, row);
            container.appendChild(row);

            draggedRow.style.position = 'fixed';
            draggedRow.style.left = `${rowRect.left}px`;
            draggedRow.style.top = `${rowRect.top}px`;
            draggedRow.style.width = `${rowRect.width}px`;
            draggedRow.style.zIndex = '9999';
            draggedRow.style.pointerEvents = 'none';
            draggedRow.style.opacity = '0.92';
            draggedRow.style.transform = 'scale(1.01)';
            draggedRow.style.boxShadow = '0 8px 20px rgba(0,0,0,0.35)';
            draggedRow.style.cursor = 'grabbing';

            window.addEventListener('pointermove', onPointerMove, { passive: false });
            window.addEventListener('pointerup', onPointerUp);
            window.addEventListener('pointercancel', onPointerUp);
        });
    });
}

// ================= HIERARCHY =================
function showHierarchy(q) {
    const container = document.createElement('div');
    container.id = 'hierarchyContainer';

    let options = [...q.options];
    if (document.getElementById('shuffleAnswers').checked) {
        shuffleArray(options);
    }

    options.forEach(opt => {
        const row = document.createElement('div');
        row.className = 'hierarchy-row';
        row.style.display = 'flex';
        row.style.alignItems = 'center';
        row.style.gap = '10px';
        row.style.borderRadius = '8px';
        row.style.transition = 'border 0.12s ease, background 0.12s ease';

        const arrows = document.createElement('div');
        arrows.style.display = 'flex';
        arrows.style.flexDirection = 'column';
        arrows.style.alignItems = 'center';
        arrows.style.gap = '4px';

        const up = document.createElement('button');
        up.type = 'button';
        up.innerText = '^';
        up.className = 'hierarchy-arrow';
        up.onclick = e => {
            e.stopPropagation();
            if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
            if (state.questionAnswered) return;

            const prev = row.previousElementSibling;
            if (prev && prev.querySelector('.hierarchy-item')) {
                container.insertBefore(row, prev);
            }
        };

        const down = document.createElement('button');
        down.type = 'button';
        down.innerText = '^';
        down.className = 'hierarchy-arrow down-arrow';
        down.onclick = e => {
            e.stopPropagation();
            if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
            if (state.questionAnswered) return;

            const next = row.nextElementSibling;
            if (next && next.querySelector('.hierarchy-item')) {
                container.insertBefore(next, row);
            }
        };

        arrows.appendChild(up);
        arrows.appendChild(down);

        const item = document.createElement('div');
        item.className = 'hierarchy-item';
        item.innerText = opt;
        item.style.flex = '1';
        item.style.touchAction = 'none';
        item.style.userSelect = 'none';
        item.style.webkitUserSelect = 'none';
        item.style.cursor = 'grab';
        item.dataset.dragDisabled = 'false';

        const fb = document.createElement('div');
        fb.className = 'hierarchy-feedback';

        row.appendChild(arrows);
        row.appendChild(item);
        row.appendChild(fb);

        container.appendChild(row);
    });

    elements.questionContainer.appendChild(container);

    const submit = document.createElement('button');
    submit.id = 'hierarchySubmit';
    submit.innerText = 'Submit';

    submit.onclick = () => {
        if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
        if (state.questionAnswered) return;
        if (isRetentionMode() && state.retentionAnswerLocked) return;

        state.questionAnswered = true;
        setHierarchyInteractionEnabled(false);

        const rows = [...container.children];
        let allCorrect = true;
        const hideFeedback = isAnswerFeedbackHidden();

        rows.forEach((r, i) => {
            const itemEl = r.querySelector('.hierarchy-item');
            const text = itemEl.innerText;
            const fb = r.querySelector('.hierarchy-feedback');

            itemEl.classList.remove('option-correct', 'option-incorrect');
            fb.classList.remove('correct-mark', 'incorrect-mark', 'missed-mark');

            if (q.options.indexOf(text) === q.correctOrder[i] - 1) {
                if (!hideFeedback) {
                    itemEl.classList.add('option-correct');
                    fb.innerText = '✔';
                    fb.classList.add('correct-mark');
                } else {
                    fb.innerText = '';
                }
            } else {
                if (!hideFeedback) {
                    itemEl.classList.add('option-incorrect');
                    fb.innerText = '✖';
                    fb.classList.add('incorrect-mark');
                } else {
                    fb.innerText = '';
                }
                allCorrect = false;
            }
        });

        applyQuestionOutcome(q, allCorrect);

        if (isSpeedMode()) {
            setTimeout(nextQuestion, CONFIG.speedDelay);
        }
    };

    elements.questionContainer.appendChild(submit);

    enableHierarchyDrag(container);
    setHierarchyInteractionEnabled(true);
}



// ================= CLASSIFY =================
function shouldUseCategoryDraggableClassifyMode() {
    return state.classifyDraggableMode === 'categories';
}

function buildClassifyImageContent(imageUrl = '', text = '', alt = 'Classify image') {
    const content = document.createElement('div');
    content.className = 'classify-item-content';

    if (imageUrl) {
        const img = document.createElement('img');
        img.className = 'classify-item-image';
        img.src = imageUrl;
        img.alt = text || alt;
        img.draggable = false;
        content.appendChild(img);

        if (text) {
            const textSpan = document.createElement('div');
            textSpan.className = 'classify-item-text classify-item-image-text';
            textSpan.innerText = text;
            content.appendChild(textSpan);
        }
    } else {
        const textSpan = document.createElement('div');
        textSpan.className = 'classify-item-text';
        textSpan.innerText = text || alt;
        content.appendChild(textSpan);
    }

    return content;
}

function showClassifyCategoriesDraggable(q) {
    const container = document.createElement('div');
    container.id = 'classifyContainer';
    container.className = 'classify-container classify-category-draggable-mode';

    const layout = document.createElement('div');
    layout.className = 'classify-layout';
    container.appendChild(layout);

    const bank = document.createElement('div');
    bank.className = 'classify-column classify-bank-column classify-drop-target';
    bank.dataset.classifyItemTarget = '';
    bank.setAttribute('role', 'button');
    bank.setAttribute('tabindex', '0');
    layout.appendChild(bank);

    const bankItems = document.createElement('div');
    bankItems.className = 'classify-bank-items';
    bank.appendChild(bankItems);

    const itemsColumn = document.createElement('div');
    itemsColumn.className = 'classify-column classify-classes-column';
    layout.appendChild(itemsColumn);

    const itemGrid = document.createElement('div');
    itemGrid.className = 'classify-category-grid classify-item-target-grid';
    itemsColumn.appendChild(itemGrid);

    const submit = document.createElement('button');
    submit.id = 'classifySubmit';
    submit.type = 'button';
    submit.innerText = 'Submit';

    const classifications = (q.classifications || []).map((classification, index) => ({
        ...classification,
        runtimeKey: `classify_category_${index}`,
        normalizedId: normalizeClassificationId(classification.id),
        dragLabel: normalizeSheetText(classification.label) || `Category ${index + 1}`
    })).filter(classification => classification.normalizedId);

    const items = (q.items || []).map((item, index) => ({
        ...item,
        runtimeKey: `classify_item_${index}`,
        correctClassificationId: normalizeClassificationId(item.correctClassificationId),
        dragLabel: item.dragLabel || item.text || `Item ${index + 1}`,
        ariaLabel: item.ariaLabel || (item.text ? `Classify item ${item.text}` : 'Classify item')
    }));

    if (document.getElementById('shuffleAnswers').checked) {
        shuffleArray(items);
    }

    const categoryPlacements = new Map();
    const progressLockedCorrectCategoryIds = new Set();
    const progressWrongCategoryIds = new Set();
    const shouldUseProgressClassifyRetry = () => isProgressMode() && !isAnswerFeedbackHidden();
    let selectedClassificationId = null;
    let suppressCategoryClickId = null;
    let progressClassifyNeedsRevision = false;
    let dragState = null;

    function preserveWindowScroll(fn) {
        const scrollX = window.scrollX;
        const scrollY = window.scrollY;
        fn();
        window.scrollTo(scrollX, scrollY);
    }

    function getScrollState() {
        return {
            bankScrollTop: bank.scrollTop,
            bankScrollLeft: bank.scrollLeft,
            itemsScrollTop: itemsColumn.scrollTop,
            itemsScrollLeft: itemsColumn.scrollLeft
        };
    }

    function restoreScrollState(scrollState) {
        if (!scrollState) return;
        const apply = () => {
            bank.scrollTop = scrollState.bankScrollTop;
            bank.scrollLeft = scrollState.bankScrollLeft;
            itemsColumn.scrollTop = scrollState.itemsScrollTop;
            itemsColumn.scrollLeft = scrollState.itemsScrollLeft;
        };
        apply();
        requestAnimationFrame(apply);
    }

    function renderStatePreservingScroll() {
        const scrollState = getScrollState();
        renderState();
        restoreScrollState(scrollState);
    }

    function getItemTargetFromPoint(clientX, clientY) {
        const el = document.elementFromPoint(clientX, clientY);
        const target = el ? el.closest('[data-classify-item-target]') : null;
        if (!target || target.classList.contains('disabled')) return null;
        return target;
    }

    function clearDropHover() {
        container.querySelectorAll('.classify-drop-target.drag-hover').forEach(target => target.classList.remove('drag-hover'));
    }

    function updateDropHover(target) {
        clearDropHover();
        if (target) target.classList.add('drag-hover');
    }

    function cleanupDragState() {
        if (!dragState) return;
        window.removeEventListener('pointermove', onDragPointerMove);
        window.removeEventListener('pointerup', onDragPointerUp);
        window.removeEventListener('pointercancel', onDragPointerUp);
        if (dragState.ghost && dragState.ghost.parentNode) dragState.ghost.parentNode.removeChild(dragState.ghost);
        if (dragState.sourceEl) dragState.sourceEl.classList.remove('drag-source');
        document.body.classList.remove('classify-dragging');
        clearDropHover();
        dragState = null;
    }

    function startDragVisual() {
        if (!dragState || dragState.dragging) return;
        dragState.dragging = true;
        document.body.classList.add('classify-dragging');

        const ghost = document.createElement('div');
        ghost.className = 'classify-drag-ghost';
        ghost.innerText = dragState.itemText;
        const rect = dragState.sourceRect;
        ghost.style.width = `${Math.max(rect.width, 140)}px`;
        ghost.style.left = `${dragState.lastClientX - dragState.offsetX}px`;
        ghost.style.top = `${dragState.lastClientY - dragState.offsetY}px`;
        document.body.appendChild(ghost);
        dragState.ghost = ghost;

        if (dragState.sourceEl) dragState.sourceEl.classList.add('drag-source');
    }

    function refreshClassifySubmitLabel() {
        if (!shouldUseProgressClassifyRetry()) {
            submit.innerText = 'Submit';
            return;
        }

        submit.innerText = progressClassifyNeedsRevision ? 'Try Again' : 'Submit';
    }

    function markClassifyCategoryRevised(classificationId) {
        if (!shouldUseProgressClassifyRetry()) return;
        const normalizedId = normalizeClassificationId(classificationId);
        if (progressLockedCorrectCategoryIds.has(normalizedId)) return;

        progressWrongCategoryIds.delete(normalizedId);
        progressClassifyNeedsRevision = false;
        refreshClassifySubmitLabel();
    }

    function getPlacedCategoriesForItem(itemRuntimeKey) {
        return classifications.filter(classification => categoryPlacements.get(classification.normalizedId) === itemRuntimeKey);
    }

    function isClassificationPlaced(classificationId) {
        return !!categoryPlacements.get(normalizeClassificationId(classificationId));
    }

    function moveCategoryToTarget(classificationId, itemRuntimeKey) {
        if (state.questionAnswered) return;
        const normalizedId = normalizeClassificationId(classificationId);
        if (!normalizedId) return;
        if (shouldUseProgressClassifyRetry() && progressLockedCorrectCategoryIds.has(normalizedId)) return;

        if (itemRuntimeKey) {
            categoryPlacements.set(normalizedId, itemRuntimeKey);
        } else {
            categoryPlacements.delete(normalizedId);
        }

        markClassifyCategoryRevised(normalizedId);
        selectedClassificationId = null;
        preserveWindowScroll(() => renderStatePreservingScroll());
    }

    function createCategoryButton(classification, location = 'bank') {
        const btn = document.createElement('div');
        btn.className = 'classify-item classify-category-drag-token';
        if (location === 'assigned') btn.classList.add('classify-assigned-category-token');
        btn.dataset.classificationId = classification.normalizedId;
        btn.setAttribute('role', 'button');
        const isProgressLockedCorrect = shouldUseProgressClassifyRetry() && progressLockedCorrectCategoryIds.has(classification.normalizedId);
        const isProgressWrong = shouldUseProgressClassifyRetry() && progressWrongCategoryIds.has(classification.normalizedId);
        btn.setAttribute('tabindex', state.questionAnswered || isProgressLockedCorrect ? '-1' : '0');
        btn.setAttribute('aria-label', `Classify category ${classification.dragLabel}`);
        btn.classList.toggle('classify-item-locked', isProgressLockedCorrect);
        if (classification.imageUrl) btn.classList.add('is-image-item');
        if (selectedClassificationId === classification.normalizedId) btn.classList.add('selected');

        btn.appendChild(buildClassifyImageContent(classification.imageUrl, classification.label, 'Category image'));

        if (!isAnswerFeedbackHidden()) {
            if (isProgressLockedCorrect) {
                btn.classList.add('option-correct');
            } else if (isProgressWrong) {
                btn.classList.add('option-incorrect');
            } else if (state.questionAnswered) {
                const placedItemKey = categoryPlacements.get(classification.normalizedId) || '';
                const placedItem = items.find(item => item.runtimeKey === placedItemKey);
                if (placedItem && normalizeClassificationId(placedItem.correctClassificationId) === classification.normalizedId) {
                    btn.classList.add('option-correct');
                } else {
                    btn.classList.add('option-incorrect');
                }
            }
        }

        if (classification.imageUrl) {
            const zoomBtn = document.createElement('button');
            zoomBtn.type = 'button';
            zoomBtn.className = 'classify-item-zoom-btn';
            zoomBtn.setAttribute('aria-label', 'Zoom category image');
            zoomBtn.setAttribute('title', 'Zoom image');
            zoomBtn.innerText = '⤢';
            const stopZoomTrigger = e => {
                e.preventDefault();
                e.stopPropagation();
            };
            zoomBtn.addEventListener('pointerdown', stopZoomTrigger);
            zoomBtn.addEventListener('click', e => {
                stopZoomTrigger(e);
                openFlashcardImageOverlay(classification.imageUrl, classification.label || 'Category image');
            });
            btn.appendChild(zoomBtn);
        }

        btn.addEventListener('pointerdown', e => {
            if (state.questionAnswered || isProgressLockedCorrect) return;
            if (e.button !== undefined && e.button !== 0 && e.pointerType !== 'touch' && e.pointerType !== 'pen') return;
            cleanupDragState();
            const rect = btn.getBoundingClientRect();
            dragState = {
                pointerId: e.pointerId,
                classificationId: classification.normalizedId,
                itemText: classification.dragLabel || 'Category',
                sourceEl: btn,
                sourceRect: rect,
                offsetX: e.clientX - rect.left,
                offsetY: e.clientY - rect.top,
                startX: e.clientX,
                startY: e.clientY,
                lastClientX: e.clientX,
                lastClientY: e.clientY,
                dragging: false,
                ghost: null
            };
            window.addEventListener('pointermove', onDragPointerMove, { passive: false });
            window.addEventListener('pointerup', onDragPointerUp);
            window.addEventListener('pointercancel', onDragPointerUp);
        });

        btn.addEventListener('click', e => {
            e.preventDefault();
            e.stopPropagation();
            btn.blur();
            if (state.questionAnswered || isProgressLockedCorrect) return;
            if (suppressCategoryClickId === classification.normalizedId) {
                suppressCategoryClickId = null;
                return;
            }
            selectedClassificationId = selectedClassificationId === classification.normalizedId ? null : classification.normalizedId;
            preserveWindowScroll(() => renderStatePreservingScroll());
        });

        btn.addEventListener('keydown', e => {
            if (state.questionAnswered || isProgressLockedCorrect) return;
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                btn.click();
            }
        });

        return btn;
    }

    function appendItemDropHeaderContent(header, item) {
        const label = normalizeSheetText(item.text);

        if (item.imageUrl) {
            const headerImageWrap = document.createElement('div');
            headerImageWrap.className = 'classify-category-header-image-wrap';

            const headerImg = document.createElement('img');
            headerImg.className = 'classify-category-header-image';
            headerImg.src = item.imageUrl;
            headerImg.alt = label || 'Classify item image';
            headerImageWrap.appendChild(headerImg);

            const zoomBtn = document.createElement('button');
            zoomBtn.type = 'button';
            zoomBtn.className = 'classify-item-zoom-btn classify-category-zoom-btn';
            zoomBtn.setAttribute('aria-label', 'Zoom item image');
            zoomBtn.setAttribute('title', 'Zoom image');
            zoomBtn.innerText = '⤢';

            const stopZoomTrigger = e => {
                e.preventDefault();
                e.stopPropagation();
            };

            zoomBtn.addEventListener('pointerdown', stopZoomTrigger);
            zoomBtn.addEventListener('click', e => {
                stopZoomTrigger(e);
                openFlashcardImageOverlay(item.imageUrl, label || 'Classify item image');
            });

            headerImageWrap.appendChild(zoomBtn);
            header.appendChild(headerImageWrap);
        }

        if (label) {
            const headerText = document.createElement('div');
            headerText.className = 'classify-category-header-text';
            headerText.innerText = label;
            header.appendChild(headerText);
        } else if (!item.imageUrl) {
            header.innerText = 'Item';
        }
    }

    function createItemDropTarget(item) {
        const placedClassifications = getPlacedCategoriesForItem(item.runtimeKey);
        const placedIds = placedClassifications.map(classification => classification.normalizedId);
        const correctId = normalizeClassificationId(item.correctClassificationId);
        const box = document.createElement('div');
        box.className = 'classify-category classify-drop-target classify-item-drop-target';
        box.dataset.classifyItemTarget = item.runtimeKey;
        box.setAttribute('role', 'button');
        box.setAttribute('tabindex', state.questionAnswered ? '-1' : '0');

        if (!state.questionAnswered && selectedClassificationId) {
            box.classList.add('is-ready');
            if (placedIds.includes(selectedClassificationId)) box.classList.add('is-active');
        }

        const header = document.createElement('div');
        header.className = 'classify-category-header';
        appendItemDropHeaderContent(header, item);
        box.appendChild(header);

        const assignment = document.createElement('div');
        assignment.className = 'classify-assigned-category-slot';
        placedClassifications.forEach(classification => {
            assignment.appendChild(createCategoryButton(classification, 'assigned'));
        });
        box.appendChild(assignment);

        if (!isAnswerFeedbackHidden() && state.questionAnswered) {
            if (placedIds.length === 1 && placedIds[0] === correctId) {
                box.classList.add('option-correct');
            } else {
                box.classList.add('option-incorrect');
            }
        }

        box.addEventListener('click', () => {
            if (state.questionAnswered) return;
            if (!selectedClassificationId) return;
            moveCategoryToTarget(selectedClassificationId, item.runtimeKey);
        });
        box.addEventListener('keydown', e => {
            if (state.questionAnswered) return;
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                if (selectedClassificationId) moveCategoryToTarget(selectedClassificationId, item.runtimeKey);
            }
        });

        return box;
    }

    function renderState() {
        bankItems.innerHTML = '';
        itemGrid.innerHTML = '';

        classifications
            .filter(classification => !isClassificationPlaced(classification.normalizedId))
            .forEach(classification => {
                bankItems.appendChild(createCategoryButton(classification, 'bank'));
            });

        items.forEach(item => {
            itemGrid.appendChild(createItemDropTarget(item));
        });

        const selectedIsPlaced = selectedClassificationId && isClassificationPlaced(selectedClassificationId);
        bank.classList.toggle('is-ready', !state.questionAnswered && !!selectedIsPlaced);
        bank.classList.toggle('is-active', !state.questionAnswered && !!selectedClassificationId && !selectedIsPlaced);
    }

    function onDragPointerMove(e) {
        if (!dragState || e.pointerId !== dragState.pointerId || state.questionAnswered) return;
        dragState.lastClientX = e.clientX;
        dragState.lastClientY = e.clientY;

        const moveX = e.clientX - dragState.startX;
        const moveY = e.clientY - dragState.startY;
        const movedEnough = Math.abs(moveX) > 6 || Math.abs(moveY) > 6;
        if (!dragState.dragging && !movedEnough) return;
        if (!dragState.dragging) {
            startDragVisual();
            suppressCategoryClickId = dragState.classificationId;
        }
        e.preventDefault();
        if (dragState.ghost) {
            dragState.ghost.style.left = `${e.clientX - dragState.offsetX}px`;
            dragState.ghost.style.top = `${e.clientY - dragState.offsetY}px`;
        }
        updateDropHover(getItemTargetFromPoint(e.clientX, e.clientY));
    }

    function onDragPointerUp(e) {
        if (!dragState || e.pointerId !== dragState.pointerId) return;
        const finishedDrag = dragState.dragging;
        const classificationId = dragState.classificationId;
        const target = finishedDrag ? getItemTargetFromPoint(e.clientX, e.clientY) : null;
        cleanupDragState();
        if (!finishedDrag || !target) return;
        moveCategoryToTarget(classificationId, target.dataset.classifyItemTarget || '');
    }

    bank.addEventListener('click', () => {
        if (state.questionAnswered) return;
        if (!selectedClassificationId) return;
        moveCategoryToTarget(selectedClassificationId, '');
    });
    bank.addEventListener('keydown', e => {
        if (state.questionAnswered) return;
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            if (selectedClassificationId) moveCategoryToTarget(selectedClassificationId, '');
        }
    });

    function handleSubmit(event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }
        if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
        if (state.questionAnswered) return;
        if (isRetentionMode() && state.retentionAnswerLocked) return;

        if (shouldUseProgressClassifyRetry() && progressClassifyNeedsRevision) {
            progressClassifyNeedsRevision = false;
            refreshClassifySubmitLabel();
            setFeedback('Move the red categories, then submit again.', false);
            return;
        }

        selectedClassificationId = null;
        cleanupDragState();

        if (shouldUseProgressClassifyRetry()) {
            let placedAnyThisAttempt = false;

            classifications.forEach(classification => {
                if (progressLockedCorrectCategoryIds.has(classification.normalizedId)) return;

                const placedItemKey = categoryPlacements.get(classification.normalizedId) || '';
                if (!placedItemKey) {
                    return;
                }

                const placedItem = items.find(item => item.runtimeKey === placedItemKey);
                placedAnyThisAttempt = true;

                if (placedItem && normalizeClassificationId(placedItem.correctClassificationId) === classification.normalizedId) {
                    progressLockedCorrectCategoryIds.add(classification.normalizedId);
                    progressWrongCategoryIds.delete(classification.normalizedId);
                } else {
                    progressWrongCategoryIds.add(classification.normalizedId);
                }
            });

            const allCorrect = items.every(item => {
                const placedIds = getPlacedCategoriesForItem(item.runtimeKey).map(classification => classification.normalizedId);
                const correctId = normalizeClassificationId(item.correctClassificationId);
                return placedIds.length === 1 && placedIds[0] === correctId && progressLockedCorrectCategoryIds.has(correctId);
            });

            if (!allCorrect) {
                const hasWrongCategories = progressWrongCategoryIds.size > 0;
                const keepGoingMessage = placedAnyThisAttempt || progressLockedCorrectCategoryIds.size > 0
                    ? 'Correct categories locked. Keep going.'
                    : 'Move any category, then submit.';
                progressClassifyNeedsRevision = hasWrongCategories;
                refreshClassifySubmitLabel();
                preserveWindowScroll(() => renderStatePreservingScroll());
                setFeedback(hasWrongCategories ? 'Try again.' : keepGoingMessage, !hasWrongCategories);
                updateNavigationButtons();
                return;
            }

            state.questionAnswered = true;
            progressClassifyNeedsRevision = false;
            refreshClassifySubmitLabel();
            preserveWindowScroll(() => renderStatePreservingScroll());
            setClassifyInteractionEnabled(false);
            applyQuestionOutcome(q, true);
            return;
        }

        state.questionAnswered = true;

        const allCorrect = items.every(item => {
            const placedIds = getPlacedCategoriesForItem(item.runtimeKey).map(classification => classification.normalizedId);
            const correctId = normalizeClassificationId(item.correctClassificationId);
            return placedIds.length === 1 && placedIds[0] === correctId;
        });

        preserveWindowScroll(() => renderStatePreservingScroll());
        setClassifyInteractionEnabled(false);
        applyQuestionOutcome(q, allCorrect);

        if (isSpeedMode()) {
            setTimeout(nextQuestion, CONFIG.speedDelay);
        }
    }

    submit.addEventListener('click', handleSubmit);
    submit.addEventListener('pointerup', e => {
        if (e.pointerType === 'touch' || e.pointerType === 'pen') {
            handleSubmit(e);
        }
    });
    submit.addEventListener('touchend', handleSubmit, { passive: false });

    elements.questionContainer.appendChild(container);
    elements.questionContainer.appendChild(submit);

    refreshClassifySubmitLabel();
    renderState();
    setClassifyInteractionEnabled(true);
}

function showClassify(q) {
    if (shouldUseCategoryDraggableClassifyMode()) {
        showClassifyCategoriesDraggable(q);
        return;
    }

    const container = document.createElement('div');
    container.id = 'classifyContainer';
    container.className = 'classify-container';

    const layout = document.createElement('div');
    layout.className = 'classify-layout';
    container.appendChild(layout);

    const bank = document.createElement('div');
    bank.className = 'classify-column classify-bank-column classify-drop-target';
    bank.dataset.classificationId = '';
    bank.setAttribute('role', 'button');
    bank.setAttribute('tabindex', '0');
    layout.appendChild(bank);

    const bankItems = document.createElement('div');
    bankItems.className = 'classify-bank-items';
    bank.appendChild(bankItems);

    const classesColumn = document.createElement('div');
    classesColumn.className = 'classify-column classify-classes-column';
    layout.appendChild(classesColumn);

    const categoryGrid = document.createElement('div');
    categoryGrid.className = 'classify-category-grid';
    classesColumn.appendChild(categoryGrid);

    const submit = document.createElement('button');
    submit.id = 'classifySubmit';
    submit.type = 'button';
    submit.innerText = 'Submit';

    const items = q.items.map((item, index) => ({
        ...item,
        runtimeKey: `classify_item_${index}`,
        dragLabel: item.dragLabel || item.text || 'Item',
        ariaLabel: item.ariaLabel || (item.text ? `Classify item ${item.text}` : 'Classify item')
    }));

    if (document.getElementById('shuffleAnswers').checked) {
        shuffleArray(items);
    }

    const placements = new Map();
    const progressLockedCorrectKeys = new Set();
    const progressWrongKeys = new Set();
    const shouldUseProgressClassifyRetry = () => isProgressMode() && !isAnswerFeedbackHidden();
    let selectedItemKey = null;
    let suppressClickRuntimeKey = null;
    let progressClassifyNeedsRevision = false;
    let dragState = null;

    function preserveWindowScroll(fn) {
        const scrollX = window.scrollX;
        const scrollY = window.scrollY;
        fn();
        window.scrollTo(scrollX, scrollY);
    }

    function getClassifyScrollState() {
        return {
            bankScrollTop: bank.scrollTop,
            bankScrollLeft: bank.scrollLeft,
            classesScrollTop: classesColumn.scrollTop,
            classesScrollLeft: classesColumn.scrollLeft
        };
    }

    function restoreClassifyScrollState(scrollState) {
        if (!scrollState) return;

        const applyScrollState = () => {
            bank.scrollTop = scrollState.bankScrollTop;
            bank.scrollLeft = scrollState.bankScrollLeft;
            classesColumn.scrollTop = scrollState.classesScrollTop;
            classesColumn.scrollLeft = scrollState.classesScrollLeft;
        };

        applyScrollState();
        requestAnimationFrame(applyScrollState);
    }

    function renderClassifyStatePreservingScroll() {
        const scrollState = getClassifyScrollState();
        renderClassifyState();
        restoreClassifyScrollState(scrollState);
    }

    function getDropTargetFromPoint(clientX, clientY) {
        const el = document.elementFromPoint(clientX, clientY);
        const target = el ? el.closest('.classify-drop-target') : null;
        if (!target || target.classList.contains('disabled')) return null;
        return target;
    }

    function clearDropHover() {
        container.querySelectorAll('.classify-drop-target.drag-hover').forEach(target => {
            target.classList.remove('drag-hover');
        });
    }

    function updateDropHover(target) {
        clearDropHover();
        if (target) {
            target.classList.add('drag-hover');
        }
    }

    function cleanupDragState() {
        if (!dragState) return;

        window.removeEventListener('pointermove', onDragPointerMove);
        window.removeEventListener('pointerup', onDragPointerUp);
        window.removeEventListener('pointercancel', onDragPointerUp);

        if (dragState.ghost && dragState.ghost.parentNode) {
            dragState.ghost.parentNode.removeChild(dragState.ghost);
        }

        if (dragState.sourceEl) {
            dragState.sourceEl.classList.remove('drag-source');
        }

        document.body.classList.remove('classify-dragging');
        clearDropHover();
        dragState = null;
    }

    function startDragVisual() {
        if (!dragState || dragState.dragging) return;

        dragState.dragging = true;
        document.body.classList.add('classify-dragging');

        const ghost = document.createElement('div');
        ghost.className = 'classify-drag-ghost';
        ghost.innerText = dragState.itemText;

        const rect = dragState.sourceRect;
        ghost.style.width = `${Math.max(rect.width, 140)}px`;
        ghost.style.left = `${dragState.lastClientX - dragState.offsetX}px`;
        ghost.style.top = `${dragState.lastClientY - dragState.offsetY}px`;

        document.body.appendChild(ghost);
        dragState.ghost = ghost;

        if (dragState.sourceEl) {
            dragState.sourceEl.classList.add('drag-source');
        }
    }

    function refreshClassifySubmitLabel() {
        if (!shouldUseProgressClassifyRetry()) {
            submit.innerText = 'Submit';
            return;
        }

        submit.innerText = progressClassifyNeedsRevision ? 'Try Again' : 'Submit';
    }

    function markClassifyItemRevised(runtimeKey) {
        if (!shouldUseProgressClassifyRetry()) return;
        if (progressLockedCorrectKeys.has(runtimeKey)) return;

        progressWrongKeys.delete(runtimeKey);
        progressClassifyNeedsRevision = false;
        refreshClassifySubmitLabel();
    }

    function moveSelectedItemTo(classificationId) {
        if (state.questionAnswered) return;
        if (!selectedItemKey) return;
        if (shouldUseProgressClassifyRetry() && progressLockedCorrectKeys.has(selectedItemKey)) return;

        const runtimeKey = selectedItemKey;
        placements.set(runtimeKey, normalizeClassificationId(classificationId));
        markClassifyItemRevised(runtimeKey);
        selectedItemKey = null;
        preserveWindowScroll(() => renderClassifyStatePreservingScroll());
    }

    function handleDroppedItem(runtimeKey, classificationId) {
        if (shouldUseProgressClassifyRetry() && progressLockedCorrectKeys.has(runtimeKey)) return;

        placements.set(runtimeKey, normalizeClassificationId(classificationId));
        markClassifyItemRevised(runtimeKey);
        selectedItemKey = null;
        preserveWindowScroll(() => renderClassifyStatePreservingScroll());
    }

    function createItemButton(item) {
        const btn = document.createElement('div');
        btn.className = 'classify-item';
        btn.dataset.runtimeKey = item.runtimeKey;
        btn.setAttribute('role', 'button');
        const isProgressLockedCorrect = shouldUseProgressClassifyRetry() && progressLockedCorrectKeys.has(item.runtimeKey);
        const isProgressWrong = shouldUseProgressClassifyRetry() && progressWrongKeys.has(item.runtimeKey);

        btn.setAttribute('tabindex', state.questionAnswered || isProgressLockedCorrect ? '-1' : '0');
        btn.setAttribute('aria-label', item.ariaLabel || 'Classify item');
        btn.classList.toggle('classify-item-locked', isProgressLockedCorrect);

        const content = document.createElement('div');
        content.className = 'classify-item-content';

        if (item.imageUrl) {
            btn.classList.add('is-image-item');

            const img = document.createElement('img');
            img.className = 'classify-item-image';
            img.src = item.imageUrl;
            img.alt = item.text || 'Classify image item';
            img.draggable = false;
            content.appendChild(img);

            if (item.text) {
                const textSpan = document.createElement('div');
                textSpan.className = 'classify-item-text classify-item-image-text';
                textSpan.innerText = item.text;
                content.appendChild(textSpan);
            }

            const zoomBtn = document.createElement('button');
            zoomBtn.type = 'button';
            zoomBtn.className = 'classify-item-zoom-btn';
            zoomBtn.setAttribute('aria-label', 'Zoom item image');
            zoomBtn.setAttribute('title', 'Zoom image');
            zoomBtn.innerText = '⤢';

            const stopZoomTrigger = e => {
                e.preventDefault();
                e.stopPropagation();
            };

            zoomBtn.addEventListener('pointerdown', stopZoomTrigger);
            zoomBtn.addEventListener('click', e => {
                stopZoomTrigger(e);
                openFlashcardImageOverlay(item.imageUrl, item.text || 'Classify image item');
            });

            btn.appendChild(zoomBtn);
        } else {
            const textSpan = document.createElement('div');
            textSpan.className = 'classify-item-text';
            textSpan.innerText = item.text;
            content.appendChild(textSpan);
        }

        btn.appendChild(content);

        if (selectedItemKey === item.runtimeKey) {
            btn.classList.add('selected');
        }

        if (!isAnswerFeedbackHidden()) {
            if (isProgressLockedCorrect) {
                btn.classList.add('option-correct');
            } else if (isProgressWrong) {
                btn.classList.add('option-incorrect');
            } else if (state.questionAnswered) {
                const placedId = normalizeClassificationId(placements.get(item.runtimeKey));
                const correctId = normalizeClassificationId(item.correctClassificationId);

                if (placedId && placedId === correctId) {
                    btn.classList.add('option-correct');
                } else {
                    btn.classList.add('option-incorrect');
                }
            }
        }

        btn.addEventListener('pointerdown', e => {
            if (state.questionAnswered || isProgressLockedCorrect) return;
            if (e.button !== undefined && e.button !== 0 && e.pointerType !== 'touch' && e.pointerType !== 'pen') return;

            cleanupDragState();

            const rect = btn.getBoundingClientRect();
            dragState = {
                pointerId: e.pointerId,
                runtimeKey: item.runtimeKey,
                itemText: item.dragLabel || item.text || 'Item',
                sourceEl: btn,
                sourceRect: rect,
                offsetX: e.clientX - rect.left,
                offsetY: e.clientY - rect.top,
                startX: e.clientX,
                startY: e.clientY,
                lastClientX: e.clientX,
                lastClientY: e.clientY,
                dragging: false,
                ghost: null
            };

            window.addEventListener('pointermove', onDragPointerMove, { passive: false });
            window.addEventListener('pointerup', onDragPointerUp);
            window.addEventListener('pointercancel', onDragPointerUp);
        });

        btn.addEventListener('click', e => {
            e.preventDefault();
            e.stopPropagation();
            btn.blur();

            if (state.questionAnswered || isProgressLockedCorrect) return;
            if (suppressClickRuntimeKey === item.runtimeKey) {
                suppressClickRuntimeKey = null;
                return;
            }

            selectedItemKey = selectedItemKey === item.runtimeKey ? null : item.runtimeKey;
            preserveWindowScroll(() => renderClassifyStatePreservingScroll());
        });

        btn.addEventListener('keydown', e => {
            if (state.questionAnswered || isProgressLockedCorrect) return;
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                btn.click();
            }
        });

        return btn;
    }

    function renderClassifyState() {
        categoryGrid.innerHTML = '';
        bankItems.innerHTML = '';

        const activeClassificationId = selectedItemKey
            ? normalizeClassificationId(placements.get(selectedItemKey))
            : null;

        q.classifications.forEach(classification => {
            const box = document.createElement('div');
            box.className = 'classify-category classify-drop-target';
            box.dataset.classificationId = classification.id;
            box.setAttribute('role', 'button');
            box.setAttribute('tabindex', '0');

            if (!state.questionAnswered && selectedItemKey) {
                box.classList.add('is-ready');
                if (activeClassificationId === classification.id) {
                    box.classList.add('is-active');
                }
            }

            const header = document.createElement('div');
            header.className = 'classify-category-header';
            if (classification.imageUrl) {
                const headerImageWrap = document.createElement('div');
                headerImageWrap.className = 'classify-category-header-image-wrap';

                const headerImg = document.createElement('img');
                headerImg.className = 'classify-category-header-image';
                headerImg.src = classification.imageUrl;
                headerImg.alt = classification.label || 'Category image';
                headerImageWrap.appendChild(headerImg);

                const zoomBtn = document.createElement('button');
                zoomBtn.type = 'button';
                zoomBtn.className = 'classify-item-zoom-btn classify-category-zoom-btn';
                zoomBtn.setAttribute('aria-label', 'Zoom category image');
                zoomBtn.setAttribute('title', 'Zoom image');
                zoomBtn.innerText = '⤢';

                const stopZoomTrigger = e => {
                    e.preventDefault();
                    e.stopPropagation();
                };

                zoomBtn.addEventListener('pointerdown', stopZoomTrigger);
                zoomBtn.addEventListener('click', e => {
                    stopZoomTrigger(e);
                    openFlashcardImageOverlay(classification.imageUrl, classification.label || 'Category image');
                });

                headerImageWrap.appendChild(zoomBtn);
                header.appendChild(headerImageWrap);
            }
            if (classification.label) {
                const headerText = document.createElement('div');
                headerText.className = 'classify-category-header-text';
                headerText.innerText = classification.label;
                header.appendChild(headerText);
            } else if (!classification.imageUrl) {
                header.innerText = 'Category';
            }

            const itemWrap = document.createElement('div');
            itemWrap.className = 'classify-category-items';

            items
                .filter(item => normalizeClassificationId(placements.get(item.runtimeKey)) === classification.id)
                .forEach(item => {
                    itemWrap.appendChild(createItemButton(item));
                });

            box.addEventListener('click', () => moveSelectedItemTo(classification.id));
            box.addEventListener('keydown', e => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    moveSelectedItemTo(classification.id);
                }
            });

            box.appendChild(header);
            box.appendChild(itemWrap);
            categoryGrid.appendChild(box);
        });

        items
            .filter(item => !normalizeClassificationId(placements.get(item.runtimeKey)))
            .forEach(item => {
                bankItems.appendChild(createItemButton(item));
            });

        bank.classList.toggle('is-active', !state.questionAnswered && !!selectedItemKey && !activeClassificationId);
        bank.classList.toggle('is-ready', !state.questionAnswered && !!selectedItemKey);
    }

    function onDragPointerMove(e) {
        if (!dragState || e.pointerId !== dragState.pointerId || state.questionAnswered) return;

        dragState.lastClientX = e.clientX;
        dragState.lastClientY = e.clientY;

        const moveX = e.clientX - dragState.startX;
        const moveY = e.clientY - dragState.startY;
        const movedEnough = Math.abs(moveX) > 6 || Math.abs(moveY) > 6;

        if (!dragState.dragging && !movedEnough) {
            return;
        }

        if (!dragState.dragging) {
            startDragVisual();
            suppressClickRuntimeKey = dragState.runtimeKey;
        }

        e.preventDefault();

        if (dragState.ghost) {
            dragState.ghost.style.left = `${e.clientX - dragState.offsetX}px`;
            dragState.ghost.style.top = `${e.clientY - dragState.offsetY}px`;
        }

        updateDropHover(getDropTargetFromPoint(e.clientX, e.clientY));
    }

    function onDragPointerUp(e) {
        if (!dragState || e.pointerId !== dragState.pointerId) return;

        const finishedDrag = dragState.dragging;
        const runtimeKey = dragState.runtimeKey;
        const target = finishedDrag ? getDropTargetFromPoint(e.clientX, e.clientY) : null;

        cleanupDragState();

        if (!finishedDrag) {
            return;
        }

        if (target) {
            handleDroppedItem(runtimeKey, target.dataset.classificationId || '');
        }
    }

    bank.addEventListener('click', () => moveSelectedItemTo(''));
    bank.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            moveSelectedItemTo('');
        }
    });

    function handleClassifySubmit(event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;
        if (state.questionAnswered) return;
        if (isRetentionMode() && state.retentionAnswerLocked) return;

        if (shouldUseProgressClassifyRetry() && progressClassifyNeedsRevision) {
            progressClassifyNeedsRevision = false;
            refreshClassifySubmitLabel();
            setFeedback('Move the red items, then submit again.', false);
            return;
        }

        selectedItemKey = null;
        cleanupDragState();

        if (shouldUseProgressClassifyRetry()) {
            let placedAnyThisAttempt = false;

            items.forEach(item => {
                if (progressLockedCorrectKeys.has(item.runtimeKey)) return;

                const placedId = normalizeClassificationId(placements.get(item.runtimeKey));
                const correctId = normalizeClassificationId(item.correctClassificationId);

                if (!placedId) {
                    return;
                }

                placedAnyThisAttempt = true;

                if (placedId === correctId) {
                    progressLockedCorrectKeys.add(item.runtimeKey);
                    progressWrongKeys.delete(item.runtimeKey);
                } else {
                    progressWrongKeys.add(item.runtimeKey);
                }
            });

            const allCorrect = items.every(item => progressLockedCorrectKeys.has(item.runtimeKey));

            if (!allCorrect) {
                const hasWrongItems = progressWrongKeys.size > 0;
                const keepGoingMessage = placedAnyThisAttempt || progressLockedCorrectKeys.size > 0
                    ? 'Correct items locked. Keep going.'
                    : 'Move any item, then submit.';
                progressClassifyNeedsRevision = hasWrongItems;
                refreshClassifySubmitLabel();
                preserveWindowScroll(() => renderClassifyStatePreservingScroll());
                setFeedback(hasWrongItems ? 'Try again.' : keepGoingMessage, !hasWrongItems);
                updateNavigationButtons();
                return;
            }

            state.questionAnswered = true;
            progressClassifyNeedsRevision = false;
            refreshClassifySubmitLabel();
            preserveWindowScroll(() => renderClassifyStatePreservingScroll());
            setClassifyInteractionEnabled(false);
            applyQuestionOutcome(q, true);
            return;
        }

        state.questionAnswered = true;

        const allCorrect = items.every(item => {
            const placedId = normalizeClassificationId(placements.get(item.runtimeKey));
            const correctId = normalizeClassificationId(item.correctClassificationId);
            return placedId && placedId === correctId;
        });

        preserveWindowScroll(() => renderClassifyStatePreservingScroll());
        setClassifyInteractionEnabled(false);
        applyQuestionOutcome(q, allCorrect);

        if (isSpeedMode()) {
            setTimeout(nextQuestion, CONFIG.speedDelay);
        }
    }

    submit.addEventListener('click', handleClassifySubmit);
    submit.addEventListener('pointerup', e => {
        if (e.pointerType === 'touch' || e.pointerType === 'pen') {
            handleClassifySubmit(e);
        }
    });
    submit.addEventListener('touchend', handleClassifySubmit, { passive: false });

    elements.questionContainer.appendChild(container);
    elements.questionContainer.appendChild(submit);

    refreshClassifySubmitLabel();
    renderClassifyState();
    setClassifyInteractionEnabled(true);
}

// ================= NAV =================
function nextQuestion() {
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;

    clearFeedback();
    clearExplanations();

    if (isQuizFinished()) {
        showQuestion();
        showPendingLearningResourceIfAny();
        return;
    }

    if (advancePastAutoStarredExcludedCurrentQuestion()) {
        return;
    }

    if (isRetentionMode()) {
        if (state.pendingRetentionJump) {
            state.currentIndex = snapIndexToTetherBuildUpRunStart(state.questionQueue, state.currentIndex - 3);
            state.pendingRetentionJump = false;
            state.pendingRetentionCorrect = false;
            state.retentionAnswerLocked = false;
            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        if (state.pendingRetentionCorrect) {
            if (state.currentIndex < state.questionQueue.length - 1) {
                state.currentIndex++;
            } else if (state.retentionSolvedIds.size === state.questionQueue.length) {
                state.retentionFinished = true;
            }

            state.pendingRetentionCorrect = false;
            state.retentionAnswerLocked = false;
            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        if (state.currentIndex < state.questionQueue.length - 1) {
            state.currentIndex++;
        } else if (state.retentionSolvedIds.size === state.questionQueue.length) {
            state.retentionFinished = true;
        }

        state.retentionAnswerLocked = false;
        showQuestion();
        showPendingLearningResourceIfAny();
        return;
    }

    if (isRetryMode()) {
        if (state.questionQueue.length === 0) {
            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        if (state.pendingMasteryAdvance) {
            state.pendingMasteryAdvance = false;

            if (state.currentIndex >= state.questionQueue.length) {
                state.currentIndex = Math.max(0, state.questionQueue.length - 1);
            }

            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        if (state.currentIndex < state.questionQueue.length - 1) {
            state.currentIndex++;
        }

        showQuestion();
        showPendingLearningResourceIfAny();
        return;
    }

    if (isMasteryCheckMode()) {
        if (state.masteryCheckPendingJump) {
            state.currentIndex = snapIndexToTetherBuildUpRunStart(state.questionQueue, state.currentIndex - 3);
            state.masteryCheckPendingJump = false;
            state.masteryCheckPendingAdvance = false;
            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        if (state.masteryCheckPendingCheckpointComplete) {
            finishMasteryCheckCheckpoint();
            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        if (state.masteryCheckPendingCheckpointStart) {
            startMasteryCheckCheckpoint();
            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        if (state.masteryCheckPendingAdvance) {
            state.masteryCheckPendingAdvance = false;

            if (state.currentIndex < state.questionQueue.length - 1) {
                state.currentIndex++;
            } else if (!state.masteryCheckInCheckpoint && state.masteryCheckSegmentQuestions.length === 0) {
                state.masteryCheckFinished = true;
            }

            showQuestion();
            showPendingLearningResourceIfAny();
            return;
        }

        showQuestion();
        showPendingLearningResourceIfAny();
        return;
    }

    if (state.currentIndex < state.questionQueue.length - 1) {
        state.currentIndex++;
    } else {
        state.normalFinished = true;
    }

    showQuestion();
    clearPendingLearningResource();
}

function prevQuestion() {
    if (state.learningResourcesOverlayOpen || state.flashcardImageZoomOpen) return;

    clearFeedback();
    clearExplanations();
    clearPendingLearningResource();
    state.flashcardFlipped = false;

    if (isRetentionMode()) {
        state.pendingRetentionJump = false;
        state.pendingRetentionCorrect = false;
        state.retentionAnswerLocked = false;

        if (state.retentionFinished) {
            state.retentionFinished = false;
            state.currentIndex = Math.max(0, state.questionQueue.length - 1);
            showQuestion();
            return;
        }

        if (state.currentIndex > 0) {
            state.currentIndex--;
        }

        showQuestion();
        return;
    }

    if (isRetryMode()) {
        if (state.pendingMasteryAdvance) {
            state.pendingMasteryAdvance = false;
        }

        if (state.currentIndex > 0) {
            state.currentIndex--;
        }

        showQuestion();
        return;
    }

    if (isMasteryCheckMode()) {
        showQuestion();
        return;
    }

    if (state.normalFinished) {
        state.normalFinished = false;
        state.currentIndex = Math.max(0, state.questionQueue.length - 1);
        showQuestion();
        return;
    }

    if (state.currentIndex > 0) {
        state.currentIndex--;
    }

    showQuestion();
}

// ================= RESET STATE =================
function resetModeState() {
    state.currentIndex = 0;
    state.studyTimer.sessionToken += 1;
    stopStudyTimer({ clearDisplay: false });
    state.autoStar.currentAttemptKey = '';
    state.autoStar.currentQuestionKey = '';
    state.autoStar.questionStartedAt = 0;
    state.autoStar.disqualifiedQuestionKeys = new Set();
    state.autoStar.pendingQuestionKeys = new Set();
    state.autoStar.excludedQuestionKeys = new Set();

    state.pendingRetentionJump = false;
    state.pendingRetentionCorrect = false;
    state.retentionAnswerLocked = false;
    state.retentionFinished = false;
    state.retentionSolvedIds = new Set();

    state.pendingMasteryAdvance = false;
    resetMasteryCheckState();

    state.progressRetryActive = false;
    state.progressWrongQuestionMap = new Map();

    state.normalFinished = false;
    state.questionAnswered = false;
    state.flashcardFlipped = false;
    state.currentQuestionType = '';
    state.completionChallengePrompt.shownForSessionKey = '';
    state.emptyQuizMessage = '';
    updateViewportClasses();

    clearPendingLearningResource();
    closeLearningResourcesOverlay();
    closeFlashcardImageOverlay();
    closeCompletionChallengePrompt();
}

// ================= RESTART =================
function restartQuiz() {
    if (!state.sourceQuestions.length && !state.questions.length) {
        clearActiveQuizSelection();
        return;
    }

    if (state.sourceQuestions.length) {
        applyFilteredQuestionsToSession({ resetSession: true });
        return;
    }

    resetModeState();
    state.questionQueue = buildStudyQuestionQueue(state.questions, {
        shuffle: !!document.getElementById('shuffleQuestions')?.checked
    });

    updateSettingsAvailability();
    showQuestion();
}

